// scripts/build-docs.mjs が docs/admin/*.html から生成する。直接編集しない。
export const ADMIN_DOCS: Record<string, { title: string; html: string }> = {"manual":{"title":"SFA 運営マニュアル","html":"<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n<style>:root{color-scheme:light dark}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%}[hidden]{display:none!important}</style>\n</head>\n<body>\n<title>SFA 運営マニュアル</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@500;700&family=Noto+Sans+JP:wght@400;500;700&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<style>\n  :root {\n    --ground: #FAFAF7;\n    --surface: #FFFFFF;\n    --ink: #1C1D21;\n    --ink-2: #5E6270;\n    --rule: #E3E3DE;\n    --accent: #2D4FA1;\n    --accent-ink: #FFFFFF;\n    --tint: #EEF2FA;\n    --warn-tint: #FBF3E4;\n    --warn-ink: #7A4B00;\n    --mono-bg: #F1F1EC;\n    --display: \"Zen Kaku Gothic New\", \"Noto Sans JP\", \"Hiragino Sans\", sans-serif;\n    --body: \"Noto Sans JP\", \"Hiragino Sans\", \"Yu Gothic\", sans-serif;\n    --mono: \"IBM Plex Mono\", \"SFMono-Regular\", Menlo, monospace;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root:not([data-theme=\"light\"]) {\n      --ground: #17181B; --surface: #1E1F24; --ink: #ECECE8; --ink-2: #A0A3AD; --rule: #2E2F35;\n      --accent: #8FA8E8; --accent-ink: #14161C; --tint: #21262F; --warn-tint: #2E2618; --warn-ink: #E8C27A; --mono-bg: #24252A;\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --ground: #17181B; --surface: #1E1F24; --ink: #ECECE8; --ink-2: #A0A3AD; --rule: #2E2F35;\n    --accent: #8FA8E8; --accent-ink: #14161C; --tint: #21262F; --warn-tint: #2E2618; --warn-ink: #E8C27A; --mono-bg: #24252A;\n  }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: var(--ground); color: var(--ink); font-family: var(--body); font-size: 15px; line-height: 1.85; }\n  a { color: var(--accent); text-decoration: none; }\n  a:hover { text-decoration: underline; text-underline-offset: 3px; }\n  a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n  .wrap { max-width: 1100px; margin: 0 auto; padding-inline: 20px; padding-block: 0 80px; }\n\n  header.top { padding-block: 48px 28px; border-bottom: 1px solid var(--rule); }\n  .eyebrow { font-family: var(--mono); font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-2); }\n  h1 { font-family: var(--display); font-weight: 700; font-size: clamp(28px, 4vw, 38px); line-height: 1.25; margin: 6px 0 10px; text-wrap: balance; letter-spacing: 0.01em; }\n  .lede { max-width: 62ch; color: var(--ink-2); margin: 0; }\n  .meta { display: flex; flex-wrap: wrap; gap: 6px 20px; margin-top: 14px; font-size: 13px; color: var(--ink-2); }\n\n  .flow { display: flex; flex-wrap: wrap; align-items: stretch; gap: 8px; margin: 24px 0 0; padding: 0; list-style: none; }\n  .flow li { display: flex; align-items: center; gap: 8px; }\n  .flow .step { background: var(--tint); border: 1px solid var(--rule); border-radius: 6px; padding: 8px 12px; font-family: var(--display); font-weight: 500; font-size: 14px; }\n  .flow .step small { display: block; font-family: var(--body); font-weight: 400; font-size: 12px; color: var(--ink-2); }\n  .flow .arrow { color: var(--ink-2); font-size: 14px; }\n\n  .layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 48px; margin-top: 28px; }\n  nav.toc { position: sticky; top: 20px; align-self: start; font-size: 13px; }\n  nav.toc .eyebrow { margin-bottom: 8px; }\n  nav.toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }\n  nav.toc a { display: grid; grid-template-columns: 22px 1fr; gap: 6px; color: var(--ink); padding: 4px 6px; border-radius: 4px; }\n  nav.toc a:hover { background: var(--tint); text-decoration: none; }\n  nav.toc .n { font-family: var(--mono); color: var(--ink-2); font-size: 12px; }\n  main { max-width: 72ch; }\n\n  section { padding-block: 40px 8px; border-top: 1px solid var(--rule); }\n  section:first-of-type { border-top: none; padding-top: 24px; }\n  h2 { font-family: var(--display); font-weight: 700; font-size: 22px; line-height: 1.35; margin: 0 0 14px; display: grid; grid-template-columns: 40px 1fr; gap: 8px; align-items: baseline; text-wrap: balance; }\n  h2 .n { font-family: var(--mono); font-weight: 500; font-size: 14px; color: var(--accent); }\n  h3 { font-family: var(--display); font-weight: 700; font-size: 16px; margin: 28px 0 8px; }\n  h4 { font-family: var(--display); font-weight: 700; font-size: 14px; margin: 18px 0 6px; color: var(--ink-2); }\n  dl.kv dd ol { margin: 8px 0; padding-left: 20px; }\n  dl.kv dd ol li { margin-bottom: 6px; }\n  p { margin: 0 0 12px; }\n  ul, ol { margin: 0 0 14px; padding-left: 1.4em; }\n  li { margin-bottom: 4px; }\n  li > ul, li > ol { margin-top: 4px; margin-bottom: 4px; }\n  strong { font-weight: 700; }\n  code, .path { font-family: var(--mono); font-size: 0.88em; background: var(--mono-bg); border-radius: 4px; padding: 1px 6px; }\n  pre { font-family: var(--mono); font-size: 13px; line-height: 1.7; background: var(--mono-bg); border: 1px solid var(--rule); border-radius: 6px; padding: 12px 14px; overflow-x: auto; margin: 0 0 14px; }\n  .btn { display: inline-block; font-family: var(--display); font-weight: 500; font-size: 0.9em; border: 1px solid var(--rule); background: var(--surface); border-radius: 5px; padding: 0 8px; line-height: 1.6; white-space: nowrap; }\n  .menu { font-family: var(--display); font-weight: 500; }\n\n  .note { background: var(--tint); border-left: 3px solid var(--accent); border-radius: 0 6px 6px 0; padding: 10px 14px; margin: 14px 0; font-size: 14px; }\n  .note.warn { background: var(--warn-tint); border-left-color: var(--warn-ink); color: var(--warn-ink); }\n  .note p:last-child { margin-bottom: 0; }\n\n  table { width: 100%; border-collapse: collapse; font-size: 14px; margin: 0 0 16px; }\n  th, td { text-align: left; vertical-align: top; padding: 8px 10px; border-bottom: 1px solid var(--rule); line-height: 1.6; }\n  th { font-family: var(--display); font-weight: 500; color: var(--ink-2); font-size: 13px; white-space: nowrap; }\n  td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }\n  .tablewrap { overflow-x: auto; }\n  dl.kv { display: grid; grid-template-columns: max-content 1fr; gap: 6px 16px; margin: 0 0 14px; font-size: 14px; }\n  dl.kv dt { font-family: var(--display); font-weight: 500; color: var(--ink-2); }\n  dl.kv dd { margin: 0; }\n\n  footer.end { margin-top: 48px; padding-top: 16px; border-top: 1px solid var(--rule); font-size: 13px; color: var(--ink-2); }\n\n  @media (max-width: 860px) {\n    .layout { grid-template-columns: 1fr; gap: 24px; }\n    nav.toc { position: static; }\n    nav.toc ol { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }\n    h2 { grid-template-columns: 34px 1fr; font-size: 20px; }\n  }\n  @media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }\n\n  /* 業務フロー図(冒頭の全体図) */\n  .fig-flow { margin: 24px 0 0; }\n  .fig-flow .scroll { overflow-x: auto; border: 1px solid var(--rule); border-radius: 8px; background: var(--surface); padding: 12px; }\n  .fig-flow svg { display: block; width: 100%; min-width: 1100px; height: auto; color: var(--ink); }\n  .fig-flow figcaption { margin-top: 8px; font-size: 12.5px; color: var(--ink-2); display: flex; flex-wrap: wrap; gap: 4px 16px; justify-content: space-between; }\n  .fig-flow .st { font-size: 12.5px; }\n  .fig-flow .hd { font-size: 15px; font-weight: 700; font-family: var(--display); }\n  .fig-flow .sm { font-size: 11.5px; }\n  .fig-flow .mu { opacity: .7; }\n  .fig-flow .box { fill: var(--surface); stroke: var(--rule); stroke-width: 1.5; }\n  .fig-flow .panel { fill: var(--tint); stroke: var(--rule); stroke-width: 1; }\n  .fig-flow .band { fill: currentColor; opacity: .07; }\n  .fig-flow .arrow { stroke: currentColor; stroke-width: 2; fill: none; }\n  .fig-flow .chip-t { font-size: 11.5px; font-weight: 600; fill: #ffffff; }\n</style>\n\n<div class=\"wrap\">\n  <header class=\"top\">\n    <p class=\"eyebrow\">Operator manual</p>\n    <h1>SFA 運営マニュアル</h1>\n    <p class=\"lede\">運営管理画面の使いかたと、サービスを動かし続けるための設定・定期処理・障害時の確認をまとめた、運営者だけが読める文書です。ご利用者(テナント)に見せる内容は利用者マニュアルに分けています。</p>\n    <div class=\"meta\">\n      <span>提供: アートトレーディング株式会社</span>\n      <span>版: 2026年9月22日(第 2 版)</span>\n      <span>対象: 運営者(運営管理にログインできる人)</span>\n      <span>関連: <a href=\"/docs/manual\" target=\"_blank\" rel=\"noopener\">利用者マニュアル</a> / <a href=\"/admin/docs/test-spec\" target=\"_blank\" rel=\"noopener\">テスト仕様書</a> / <a href=\"/docs/flow\" target=\"_blank\" rel=\"noopener\">業務フロー図</a></span>\n    </div>\n    <div class=\"note warn\"><p>この文書とテスト仕様書は運営者としてログインしているときだけ開けます。設定値やドメインの構成を含むので、社外やご利用者に転送しないでください。パスワードやアプリパスワードなどの秘密の値は、この文書には書かず、Vercel の環境変数にだけ保存します。</p></div>\n  </header>\n\n  <div class=\"layout\">\n    <nav class=\"toc\" aria-label=\"目次\">\n      <p class=\"eyebrow\">目次</p>\n      <ol>\n        <li><a href=\"#s1\"><span class=\"n\">1</span>運営管理に入る</a></li>\n        <li><a href=\"#s2\"><span class=\"n\">2</span>テナント(契約企業)</a></li>\n        <li><a href=\"#s3\"><span class=\"n\">3</span>料金・既定値</a></li>\n        <li><a href=\"#s4\"><span class=\"n\">4</span>エラー通知と監視</a></li>\n        <li><a href=\"#s5\"><span class=\"n\">5</span>ユーザー管理(運営者)</a></li>\n        <li><a href=\"#s6\"><span class=\"n\">6</span>メールテンプレート</a></li>\n        <li><a href=\"#s7\"><span class=\"n\">7</span>メール転送の受け口</a></li>\n        <li><a href=\"#s8\"><span class=\"n\">8</span>環境変数と定期処理</a></li>\n        <li><a href=\"#s9\"><span class=\"n\">9</span>困ったときは</a></li>\n      </ol>\n    </nav>\n\n    <main>\n      <section id=\"s1\">\n        <h2><span class=\"n\">01</span>運営管理に入る</h2>\n        <p>運営者のアカウントでログインすると <span class=\"path\">https://sfa.art-trading.net/admin</span> が使えます。上のメニューは <span class=\"menu\">テナント</span>、<span class=\"menu\">ユーザー管理</span>、<span class=\"menu\">メールテンプレート</span>、<span class=\"menu\">料金・既定値</span>、<span class=\"menu\">運営マニュアル</span>(この文書)です。</p>\n        <dl class=\"kv\">\n          <dt>運営専用のアカウント</dt><dd>まだ登録のないメールアドレスを招待して作ったアカウント。どの会社にも所属しないので、テナント側の画面には入れません(ログアウトのみ)。</dd>\n          <dt>自社の利用者を兼ねる運営者</dt><dd>運営側の会社(最初に作られたテナント=自社)の利用者は、そのままのログインで運営者にもなれます。テナント側のサイドバーの下に「運営管理」が出て、運営管理の右上の「アプリへ戻る」で行き来できます。</dd>\n          <dt>スーパーユーザー</dt><dd>運営者の招待と削除ができる運営者です(<a href=\"#s5\">5 章</a>)。</dd>\n        </dl>\n        <p>他社(自社以外のテナント)の利用者は運営者にできません。</p>\n      </section>\n\n      <section id=\"s2\">\n        <h2><span class=\"n\">02</span>テナント(契約企業)</h2>\n        <h3>テナント一覧</h3>\n        <p>全社の会社名・担当者・契約状態・課金状態・お試し期限・ユーザー数・メールアカウント数・メール件数・容量・月額(利用数ベース)と、課金中の月額合計が見られます。会社名から詳細を開きます。</p>\n        <h3>テナントの詳細</h3>\n        <dl class=\"kv\">\n          <dt>会社情報・連絡先</dt><dd>会社名、担当者名、メール、電話、住所、運営メモ。運営メモはご利用者には見えません。</dd>\n          <dt>利用状況</dt><dd>ユーザー数(招待中を含む)、メールアカウント数、メール件数、使用容量と、それぞれの上限。</dd>\n          <dt>契約・上限・課金状態</dt><dd>契約状態(お試し / 契約中 / 停止 / 解約)、お試し期限(その日の終わりまで有効)、ユーザー数・メールアカウント数・容量(GB)の上限、課金状態。停止・解約・お試し期限切れの会社は閲覧のみになり、登録や送信ができません。</dd>\n          <dt>Stripe(オンライン決済)</dt><dd>顧客・サブスクリプションの状況と、利用数(基本 1 + ユーザー追加 + メールアカウント追加)を Stripe の数量に合わせ直すボタン。通常は招待・削除・メールアカウントの追加削除のたびに自動で同期されます。</dd>\n          <dt>利用者(営業担当者)</dt><dd>その会社の営業担当者とログインの状態。招待メールの再送ができます。</dd>\n          <dt>テナントの削除</dt><dd>会社のデータをすべて消します。元に戻せません。</dd>\n        </dl>\n        <div class=\"note\"><p>運営が手で「停止」にした会社は、Stripe からの通知(Webhook)で契約状態が上書きされません。再開するときは運営が手で戻します。それ以外は Stripe の状態がそのまま写ります(お試し中 → お試し、支払い済み → 契約中、支払い遅延 → 契約中 + 支払い遅延、未払い・一時停止 → 停止、解約 → 解約)。</p></div>\n        <div class=\"note\"><p>使用容量には、ご利用者がゴミ箱に入れたメール(14 日間)も含まれます。上限に近い会社から相談があれば、ゴミ箱を空にすると減る場合があります。</p></div>\n        <h3>テナントを作成する</h3>\n        <p>Web 申し込み(<span class=\"path\">/signup</span>)を使わずに運営が会社を作る場合に使います。会社名、会社 ID、住所・電話、最初の管理者の担当者名とメールアドレス、上限(ユーザー数・メールアカウント数・容量)とお試し期間(日)、運営メモを入力すると、最初の管理者宛てに招待メールが送られます。</p>\n        <h3>メールアカウントの上限を上げるとき</h3>\n        <p>ご利用者から「メールアカウントを追加できない」と連絡があったら、テナントの詳細 → 契約・上限・課金状態の「メールアカウント数の上限」を上げます。基本料金に含まれるのは 1 件で、2 件目からオプション料金がかかります(<a href=\"#s3\">3 章</a>)。メール転送で受信するアカウントも 1 件として数えます。</p>\n      </section>\n\n      <section id=\"s3\">\n        <h2><span class=\"n\">03</span>料金・既定値</h2>\n        <p><span class=\"menu\">料金・既定値</span> で、月額の基本料金、追加ユーザー・追加メールアカウントの単価(いずれも税抜・円/月)、新規テナントの既定の上限とお試し期間を決めます。</p>\n        <ul>\n          <li>申し込み画面の料金表、紹介ページ(LP)、特定商取引法に基づく表記の価格は、ここの値に連動します。</li>\n          <li>請求は Stripe の数量課金で、消費税 10% を外税で加算します(円未満切り捨て)。単価を変えると、その単価の Price が Stripe に無ければ自動で作られます。</li>\n          <li>既定の上限とお試し期間は、変更後に作られるテナントから適用されます。既存の会社は詳細画面で個別に変えます。</li>\n        </ul>\n      </section>\n\n      <section id=\"s4\">\n        <h2><span class=\"n\">04</span>エラー通知と監視</h2>\n        <h3>エラー通知先(運営)</h3>\n        <p><span class=\"menu\">料金・既定値</span> のページの下にあります。システム全体のエラー、各テナントで起きたエラーの控え(件名にテナント名付き)、Web からの新規申し込みを、通知先メールアドレス(カンマ区切りで複数可)と Lark のグループチャット(カスタムボットの Webhook URL。署名検証を使う場合はシークレットも)へ送ります。<span class=\"btn\">テスト通知を送る</span> で確認できます。</p>\n        <ul>\n          <li>各テナント自身のエラーは、そのテナントの設定画面の通知先にも届きます。</li>\n          <li>同じ原因のエラーは 30 分に 1 回にまとめて通知されます。</li>\n          <li>各テナントで起きたことの記録は、その会社の「設定 → ログ」で見られます。会社に属さないシステム全体のエラーは、この通知先に届きます。</li>\n        </ul>\n        <h3>定期ヘルスチェック</h3>\n        <p>毎日 1 回、データベース、全テナントのメールアカウント(IMAP / SMTP。メール転送で受信するアカウントは SMTP のみ)、メール転送の受け口(<a href=\"#s7\">7 章</a>)への接続を確認し、結果をログに残します。失敗があるとエラー通知先に届きます。<span class=\"path\">/api/health</span> は外形監視にも使えます(未ログインではデータベースの確認だけを返します)。</p>\n      </section>\n\n      <section id=\"s5\">\n        <h2><span class=\"n\">05</span>ユーザー管理(運営者)</h2>\n        <p>運営管理に入れる人の招待と削除です。スーパーユーザーだけが操作できます。</p>\n        <ul>\n          <li>運営側の会社(自社)の利用者のメールアドレスを追加すると、その人は今のログインのまま運営者にもなります。削除すると運営者から外れるだけで、テナント側のログインは残ります。</li>\n          <li>まだ登録のないメールアドレスを招待すると、運営専用のアカウントになります。招待メールのリンクからパスワードを設定します。削除するとアカウントごと消えます。</li>\n          <li>他社の利用者のメールアドレスは追加できません。</li>\n          <li>氏名とメモは一覧の鉛筆ボタンで編集できます。</li>\n        </ul>\n      </section>\n\n      <section id=\"s6\">\n        <h2><span class=\"n\">06</span>メールテンプレート</h2>\n        <p>申し込み確認、招待、パスワード再設定など、アプリが送るメールの件名と本文です。<code>{{name}}</code> や <code>{{link}}</code> などの差し込みが使え、プレビューで確認できます。編集しなければ既定の文面が使われます。</p>\n        <p>申し込み確認や運営からの招待メールは、運営側の会社(最初に作られたテナント)の既定メールアカウントから送られます。そのアカウントの接続が切れると申し込みの確認メールが送れなくなるので、エラー通知が来たら早めに接続テストをしてください。</p>\n        <div class=\"note\"><p>ご利用者が営業メールに使う「メールテンプレート」(設定画面)とは別のものです。</p></div>\n        <h3>ステップメール</h3>\n        <p>メニューの「ステップメール」で、お試し中の顧客(テナントの連絡先メール)へ、テナント作成からの日数に合わせて自動で送るメールを管理します。既定で 6 回(0 / 1 / 3 / 7 / 14 / 21 日目)の文面が入っています。行を押すと件名・本文・送信日(登録から何日後)を編集でき、「サンプルでプレビュー」「自分にテスト送信」で確認できます。回の追加・削除・「有効」の切り替えも同じ画面です。</p>\n        <ul>\n          <li>送るタイミングは毎朝の定期処理(7:00 ごろ)。本文の末尾には運営の会社名と問い合わせ先が自動で付きます。</li>\n          <li>差出人は一覧の下の「送信元」で決めます。空のままなら運営側の既定メールアカウントから、そのアカウントの名前とアドレスで送ります。「送信に使うアカウント」で運営側の別のアカウントを選べ、「差出人アドレス」「差出人名」を入れるとその名前・アドレスで届きます(「自分にテスト送信」も同じ送信元)。差出人アドレスを変えても送信(SMTP)は選んだアカウントで行うので、そのアカウントで送信できるアドレス(Gmail の「他のメールアドレスから送信」で登録したエイリアスなど)だけが使えます。登録していないアドレスはサーバー側でアカウントのアドレスに書き換えられるか、送信を拒否されます。返信先(Reply-To)には差出人アドレスが付きます。選んだアカウントが無効化・削除されていたときは既定のアカウントで送り、履歴の理由欄にその旨が残ります。</li>\n          <li>カード登録(課金開始)・停止・解約になったテナントには、「課金開始後も送る」にした回(既定では 1 日目・3 日目の使い方の案内)だけ送ります。7 / 14 / 21 日目のカード登録の案内は未課金のテナントだけです。</li>\n          <li>予定日から 2 日以上過ぎた回は送らずに「見送り」として記録します。定期処理が 1 日止まっても翌日に追いつきます。</li>\n          <li>この機能を入れた 2026 年 9 月 22 日より前からあるテナントは「送らない」になっています。送りたい場合はテナント詳細の「ステップメール」で「このテナントにステップメールを送る」をオンにしてください(以後の回だけが対象です)。</li>\n          <li>テナント詳細の「ステップメール」に、回ごとの結果(送信済み / 失敗 / 見送り)と宛先・日時・理由が並びます。失敗は運営のエラー通知先にも届きます。宛先が無い(連絡先メールが空で利用者もいない)テナントは失敗になるので、連絡先を入れてください。</li>\n          <li>差し込み: <code>{{name}}</code> 担当者名(連絡先)、<code>{{company}}</code> 会社名、<code>{{app_name}}</code>、<code>{{login_link}}</code>、<code>{{billing_link}}</code>(お支払い設定)、<code>{{manual_link}}</code>、<code>{{trial_end}}</code>(お試し期限の日付)、<code>{{days_left}}</code>(期限までの日数)。</li>\n        </ul>\n      </section>\n\n      <section id=\"s7\">\n        <h2><span class=\"n\">07</span>メール転送の受け口</h2>\n        <p>IMAP で連携できないメールサービス(Microsoft 365 など)のご利用者は、「メール転送で受信」を使います(利用者マニュアル 2 章)。その転送先になるのが、全テナント共通の<strong>受信用メールボックス</strong>です。運営側で 1 つ用意し、アプリが IMAP で読みに行って、宛先に含まれるトークンでどのテナントのどのアカウント宛てかを決めます。ご利用者にはアカウントごとの受け口アドレスだけが見え、このメールボックスのログイン情報は見えません。</p>\n        <h3>現在の構成</h3>\n        <dl class=\"kv\">\n          <dt>メールボックス</dt><dd><code>sfa-inbox@in.sfa.art-trading.net</code>(Google Workspace、art-trading.co.jp の組織の専用ユーザー)</dd>\n          <dt>受け口アドレスの形</dt><dd><code>sfa-inbox+トークン 20 文字@in.sfa.art-trading.net</code>(Gmail のプラスアドレス)</dd>\n          <dt>ドメイン</dt><dd><code>in.sfa.art-trading.net</code> を Workspace のセカンダリドメインとして追加。DNS はお名前.com。</dd>\n          <dt>art-trading.net 本体</dt><dd>メールは Lark で運用中です。本体の MX・SPF には手を入れません。</dd>\n        </dl>\n        <h3>作り直す・別の環境に用意するときの手順</h3>\n        <ol>\n          <li><strong>ドメインを追加</strong>: Google 管理コンソール → アカウント → ドメイン → ドメインの管理 → <span class=\"btn\">ドメインを追加</span> で、「セカンダリドメイン」として登録します。続く画面で所有権確認の TXT レコードの値(<code>google-site-verification=…</code>)が表示されます。</li>\n          <li><strong>DNS に 2 行追加</strong>(お名前.com の DNS レコード設定):\n            <div class=\"tablewrap\"><table>\n              <thead><tr><th>ホスト名</th><th>TYPE</th><th>VALUE</th><th>優先</th></tr></thead>\n              <tbody>\n                <tr><td><code>in.sfa</code></td><td>TXT</td><td><code>google-site-verification=…</code>(手順 1 の値)</td><td>-</td></tr>\n                <tr><td><code>in.sfa</code></td><td>MX</td><td><code>smtp.google.com</code></td><td>1</td></tr>\n              </tbody>\n            </table></div>\n            「追加」のあと、画面下の「確認画面へ進む」→「設定する」まで押して保存します。反映には 10 分ほどかかります。\n          </li>\n          <li><strong>所有権の確認と Gmail の有効化</strong>: DNS に反映されたら、管理コンソールの画面で <span class=\"btn\">確認</span> を押します。「所有権が証明されました」「Gmail の使用準備が整いました」と出れば完了です。早すぎると「現在確認できません」になるので、少し待って再試行します。</li>\n          <li><strong>専用ユーザーを作成</strong>: ディレクトリ → ユーザー → 新しいユーザーの追加で、@ の右のドメインに <code>in.sfa.art-trading.net</code> を選んで作ります(ライセンス 1 名分)。</li>\n          <li><strong>初回ログインと 2 段階認証</strong>: 組織で 2 段階認証が必須のため、作ったばかりのユーザーは「2 段階認証プロセスのポリシーを遵守していません」と出てログインできません。管理コンソールでそのユーザーを開き、セキュリティ → 2 段階認証プロセス → <span class=\"btn\">バックアップ確認コードを取得</span> で発行したコードを使ってログインし、すぐに 2 段階認証を登録します(引き継ぎしやすい認証アプリがおすすめ)。</li>\n          <li><strong>アプリパスワードと IMAP</strong>: そのユーザーで <span class=\"path\">https://myaccount.google.com/apppasswords</span> からアプリパスワード(16 桁)を発行し、Gmail の設定 → メール転送と POP/IMAP で IMAP が有効なことを確認します。</li>\n          <li><strong>環境変数を登録して再デプロイ</strong>: Vercel の Production に次の 5 つを登録し、再デプロイします。揃うと、テナントの設定画面のメールサービスに「メール転送で受信」が出ます。どれかが欠けている間は選択肢に出ず、保存もできません。\n            <div class=\"tablewrap\"><table>\n              <thead><tr><th>名前</th><th>値</th></tr></thead>\n              <tbody>\n                <tr><td><code>INBOUND_IMAP_HOST</code></td><td><code>imap.gmail.com</code></td></tr>\n                <tr><td><code>INBOUND_IMAP_PORT</code></td><td><code>993</code></td></tr>\n                <tr><td><code>INBOUND_IMAP_USER</code></td><td><code>sfa-inbox@in.sfa.art-trading.net</code></td></tr>\n                <tr><td><code>INBOUND_IMAP_PASSWORD</code></td><td>アプリパスワード(空白は入っていても構いません)</td></tr>\n                <tr><td><code>INBOUND_ADDRESS_FORMAT</code></td><td><code>sfa-inbox+{token}@in.sfa.art-trading.net</code>(<code>{token}</code> はそのまま書きます)</td></tr>\n              </tbody>\n            </table></div>\n          </li>\n        </ol>\n        <div class=\"note warn\">\n          <p><strong>DNS のホスト名の欄を空にしないでください。</strong>空のまま登録すると art-trading.net 本体に入ります。本体の MX に <code>smtp.google.com</code> が並ぶと、Lark で受けている @art-trading.net 宛てのメールの一部が Google に配送されて送信者に戻ってしまいます。保存後は、一覧のホスト名が <code>in.sfa.art-trading.net</code> になっていること、本体の MX が Lark の 3 行だけであることを確認します。</p>\n        </div>\n        <h3>運用上の決まり</h3>\n        <ul>\n          <li><strong>このメールボックスは専用にします。</strong>ほかの用途のメールを受けたり、人が普段使いしたりしないでください。毎朝の定期処理が、どのアカウント宛てでもないメール(Google からのセキュリティ通知など)を既読にして取り込みの対象から外し、受信から 30 日を過ぎたメールを削除します。</li>\n          <li>取り込めたメールは、その場で受信箱から消えます。取り込みに失敗したメールや、利用停止中の会社宛てのメールは未読のまま残り、次の同期でやり直します(30 日で削除)。</li>\n          <li>取り込みのタイミングは、各テナントの <span class=\"btn\">今すぐ同期</span> と、5 分おきの定期同期です。テナントの同期は自分の会社宛てのメールだけを取り込み、他社宛てには触りません。</li>\n          <li>アプリパスワードを作り直したら、<code>INBOUND_IMAP_PASSWORD</code> を更新して再デプロイします。古いままだと、ヘルスチェックと各テナントの同期が「転送メールの受信用メールボックスに接続できません」で失敗します。</li>\n          <li><strong>受け口のドメインやアドレスの形は変えないでください。</strong>変えると、全テナントがメールサーバーの転送先を設定し直すことになります。</li>\n          <li>Gmail は同じ Message-ID のメールを 1 通にまとめます。まったく同じメールが 2 つのテナントから同時に転送されると、片方にしか取り込まれません。問題になったら、catch-all が使えるメールサーバーに受け口を移します(アドレスの形は <code>INBOUND_ADDRESS_FORMAT</code> で変えられますが、上の理由で移行は慎重に)。</li>\n          <li>転送されたメールは差出人の認証(SPF / DMARC)が崩れるため、Gmail の迷惑メールに振り分けられることがよくあります(2026-09-24 の実機テストでは 4 通すべてが迷惑メールに入りました)。アプリは受信トレイと迷惑メールフォルダの両方を走査して取り込むので、迷惑メールに入っても届きます。ただし Gmail は迷惑メールを 30 日で自動削除するので、念のためこのメールボックスの Gmail で「宛先 <code>sfa-inbox</code>」→「迷惑メールにしない」のフィルタを作っておくと安全です。</li>\n        </ul>\n        <h3>ご利用者から問い合わせが来たら</h3>\n        <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>内容</th><th>確認すること</th></tr></thead>\n          <tbody>\n            <tr><td>選択肢に「メール転送で受信」が出ない</td><td>Vercel の Production に <code>INBOUND_*</code> の 5 つが揃っているか、登録後に再デプロイしたか。</td></tr>\n            <tr><td>追加できない</td><td>メールアカウント数の上限(<a href=\"#s2\">2 章</a>)。</td></tr>\n            <tr><td>「転送待ち」のまま届かない</td><td>ご利用者のメールサーバーの転送先が、設定画面の受け口アドレスと一致しているか(再発行すると変わります)。Microsoft 365 は管理者が外部への自動転送を許可しているか。受信用メールボックスの受信トレイと迷惑メールに、そのアドレス宛てのメールが来ているか(迷惑メールに入っていても取り込まれます)。届いていれば、ご利用者側で <span class=\"btn\">同期</span> または転送設定の確認ボタンを押してもらいます(自動の取り込みは 5 分おきです)。</td></tr>\n            <tr><td>受信はできるが送信できない</td><td>ご利用者のメールサービスで SMTP 認証が無効(Microsoft 365 で多い)。その場合は受信のみの利用になります。</td></tr>\n            <tr><td>受け口アドレスが外部に漏れた</td><td>ご利用者の設定画面で <span class=\"btn\">アドレスを再発行</span> し、メールサーバーの転送先を新しいアドレスに変えてもらいます。</td></tr>\n          </tbody>\n        </table>\n        </div>\n      </section>\n\n      <section id=\"s8\">\n        <h2><span class=\"n\">08</span>環境変数と定期処理</h2>\n        <p>環境変数は Vercel のプロジェクト設定(Production)に登録します。変更したら再デプロイが必要です。秘密の値はここには書きません。</p>\n        <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>名前</th><th>用途</th></tr></thead>\n          <tbody>\n            <tr><td><code>NEXT_PUBLIC_SUPABASE_URL</code> / <code>NEXT_PUBLIC_SUPABASE_ANON_KEY</code> / <code>SUPABASE_SERVICE_ROLE_KEY</code></td><td>データベース(Supabase)。service role は招待・添付ファイルの実体・テナント一覧などに限って使います。</td></tr>\n            <tr><td><code>SUPABASE_JWT_SECRET</code></td><td>定期同期・ヘルスチェックが、テナントごとの権限で動くために使います。</td></tr>\n            <tr><td><code>CRON_SECRET</code></td><td>定期処理の呼び出しを認証する共有シークレット。</td></tr>\n            <tr><td><code>NEXT_PUBLIC_SITE_URL</code> / <code>NEXT_PUBLIC_LP_HOST</code></td><td>本体の URL(招待・確認メールのリンク、決済の戻り先)と、紹介ページ専用のドメイン。</td></tr>\n            <tr><td><code>STRIPE_SECRET_KEY</code> / <code>STRIPE_WEBHOOK_SECRET</code></td><td>オンライン決済。未設定の間、ご利用者の課金画面は「準備中」表示になり、申し込みだけが動きます。</td></tr>\n            <tr><td><code>INBOUND_IMAP_*</code> / <code>INBOUND_ADDRESS_FORMAT</code></td><td>メール転送の受け口(<a href=\"#s7\">7 章</a>)。</td></tr>\n            <tr><td><code>ALERT_WEBHOOK_URL</code></td><td>任意。エラー通知を追加で送る Webhook。</td></tr>\n            <tr><td><code>ANTHROPIC_API_KEY</code></td><td>任意。メール本文からの会社名・氏名の抽出に AI を使います。</td></tr>\n            <tr><td><code>MAIL_CREDENTIALS_KEY</code></td><td>任意。メールアカウントのパスワードを暗号化する鍵(未設定なら service role のキーから導出)。途中で変えると保存済みのパスワードが読めなくなります。</td></tr>\n          </tbody>\n        </table>\n        </div>\n        <h3>定期処理(Vercel Cron、<code>vercel.json</code>)</h3>\n        <dl class=\"kv\">\n          <dt>メールの定期同期(5 分おき)</dt><dd><code>/api/mail/sync</code>。利用できる状態の全テナント(契約中と、期限内のお試し)のメールを順に取り込みます。新着メールのチャット通知もこのタイミングで届きます。取り込みかエラーがあった回だけ、各テナントのログに「定期同期: n 件取り込み」と残ります(何も無かった回は記録しません。アカウントごとの最終同期は設定画面の各アカウントに出ます)。停止・解約・お試し期限切れの会社は同期の対象外です。</dd>\n          <dt>毎朝の定期処理(7:00 ごろ)</dt><dd><code>/api/mail/maintenance</code>。全テナントのゴミ箱の期限切れ(14 日超)の完全削除、ステップメールの送信(<a href=\"#s6\">6 章</a>)、メール転送の受け口の掃除を行い、システム全体のログに「毎朝の定期処理: 完了」と残ります。ステップメールだけを手で走らせたいときは <code>/api/step-mails/run</code> を <code>Authorization: Bearer &lt;CRON_SECRET&gt;</code> 付きで呼びます。</dd>\n          <dt>定期ヘルスチェック(8:00 ごろ)</dt><dd><a href=\"#s4\">4 章</a>のとおり。</dd>\n        </dl>\n        <h3>データベースの変更</h3>\n        <p>スキーマの変更は <code>supabase/migrations/</code> の SQL を 1 ファイルずつ適用します。<strong>先に適用してから</strong>アプリを公開します(逆にすると、新しい列を読む画面が空になります)。適用に使う Supabase のアクセストークンは失効することがあり、その場合は再発行します。</p>\n      </section>\n\n      <section id=\"s9\">\n        <h2><span class=\"n\">09</span>困ったときは</h2>\n        <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>症状</th><th>確認すること</th></tr></thead>\n          <tbody>\n            <tr><td>申し込みの確認メール・招待メールが届かない</td><td>運営側の会社の既定メールアカウントで接続テスト。迷惑メールフォルダ。リンクの有効期限は 24 時間です。</td></tr>\n            <tr><td>定期同期のログが出ていない</td><td><code>CRON_SECRET</code> と <code>SUPABASE_JWT_SECRET</code> が設定されているか。Vercel の Cron の実行履歴。</td></tr>\n            <tr><td>ログに「転送メールの受け口に宛先不明のメールが n 件届きました」</td><td>受信用メールボックスに、どのアカウント宛てでもないメールが届いた記録です。Google からの通知や迷惑メールなら対応不要です。件数が急に増えたら、削除済みのアカウント宛てに転送が残っていないか、受け口アドレスが漏れていないかを確認します。</td></tr>\n            <tr><td>「転送メールの受信用メールボックスに接続できません」</td><td>アプリパスワードの失効・作り直し、専用ユーザーの停止、IMAP の無効化。直したら <code>INBOUND_IMAP_PASSWORD</code> を更新して再デプロイします。</td></tr>\n            <tr><td>契約状態が Stripe と合わない</td><td>テナントの詳細の Stripe の欄で状況を確認し、数量の同期ボタンを押します。運営が手で「停止」にした会社は自動では戻りません。</td></tr>\n            <tr><td>特定の会社でだけエラーが出る</td><td>通知メールの件名にテナント名が入っています。その会社の「設定 → ログ」で前後の記録を確認します。</td></tr>\n            <tr><td>ご利用者から「メールが消えた」と言われた</td><td>順に確認します。(1) メール一覧の右上「ゴミ箱」に入っていないか(削除は 14 日間ゴミ箱に残り、誰がいつ消したかも出ます。「元に戻す」で戻せます)。(2) 一覧は新しい順 300 通ずつなので、古いメールは「さらに表示」か検索で出るか。(3) Gmail 側でフィルタ(受信トレイをスキップ)や迷惑メール判定で受信トレイに入らなかったメールは取り込まれません。(4) 削除したメールは同期でも戻らないので、ゴミ箱から完全に削除した後(または 14 日経過後)は復元できません。</td></tr>\n            <tr><td>ステップメールが届かない・届きすぎる</td><td>テナント詳細の「ステップメール」の履歴を見ます。「見送り」の理由(予定日超過・課金開始後)と、「このテナントにステップメールを送る」のオン/オフ、回の「有効」を確認します。導入前(2026 年 9 月 22 日より前)のテナントは既定でオフです。失敗は運営のエラー通知先にも届きます。</td></tr>\n            <tr><td>ステップメールの差出人が設定と違う</td><td>ステップメールの「送信元」の差出人アドレスは、選んだアカウントで送信できるエイリアスに限ります。Gmail なら「設定 → アカウント → 他のメールアドレスから送信」に登録してから使います。未登録だと Gmail がアカウントのアドレスに書き換えます。「自分にテスト送信」で届いた差出人を確認してください。</td></tr>\n          </tbody>\n        </table>\n        </div>\n      </section>\n\n      <footer class=\"end\">\n        この文書は 2026年9月20日 時点の機能にもとづいています。本文は <code>docs/admin/manual.html</code>、公開用の変換は <code>node scripts/build-docs.mjs</code>。\n      </footer>\n    </main>\n  </div>\n</div>\n\n</body>\n</html>\n"},"test-spec":{"title":"SFA テスト仕様書","html":"<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n<style>:root{color-scheme:light dark}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%}[hidden]{display:none!important}</style>\n</head>\n<body>\n<title>SFA テスト仕様書</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Zen+Kaku+Gothic+New:wght@500;700&family=Noto+Sans+JP:wght@400;500;700&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<style>\n  :root {\n    --paper: #f5f7f9;\n    --surface: #ffffff;\n    --surface-2: #eef1f4;\n    --ink: #1a2330;\n    --ink-2: #4a5665;\n    --ink-3: #7b8794;\n    --line: #d7dde4;\n    --line-2: #e6eaee;\n    --accent: #0f6e56;\n    --accent-ink: #ffffff;\n    --accent-soft: #e3f1ec;\n    --warn: #9a6a0c;\n    --warn-soft: #fbf1d9;\n    --bad: #b42318;\n    --bad-soft: #fbe3e0;\n    --hold: #5b6b7c;\n    --hold-soft: #e7ebef;\n    --shadow: 0 1px 2px rgba(20, 30, 40, .06), 0 8px 24px -16px rgba(20, 30, 40, .25);\n    color-scheme: light;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root:not([data-theme=\"light\"]) {\n      --paper: #131a21;\n      --surface: #1a232c;\n      --surface-2: #212c37;\n      --ink: #e8edf2;\n      --ink-2: #b4bfca;\n      --ink-3: #7f8b97;\n      --line: #33404d;\n      --line-2: #283340;\n      --accent: #4fc0a0;\n      --accent-ink: #0d1a16;\n      --accent-soft: #1b3a32;\n      --warn: #e2b04a;\n      --warn-soft: #3a2f14;\n      --bad: #f08a80;\n      --bad-soft: #43201d;\n      --hold: #aab6c2;\n      --hold-soft: #2a3542;\n      --shadow: 0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.6);\n      color-scheme: dark;\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --paper: #131a21;\n    --surface: #1a232c;\n    --surface-2: #212c37;\n    --ink: #e8edf2;\n    --ink-2: #b4bfca;\n    --ink-3: #7f8b97;\n    --line: #33404d;\n    --line-2: #283340;\n    --accent: #4fc0a0;\n    --accent-ink: #0d1a16;\n    --accent-soft: #1b3a32;\n    --warn: #e2b04a;\n    --warn-soft: #3a2f14;\n    --bad: #f08a80;\n    --bad-soft: #43201d;\n    --hold: #aab6c2;\n    --hold-soft: #2a3542;\n    --shadow: 0 1px 2px rgba(0,0,0,.4), 0 8px 24px -16px rgba(0,0,0,.6);\n    color-scheme: dark;\n  }\n\n  * { box-sizing: border-box; }\n  body {\n    margin: 0;\n    background: var(--paper);\n    color: var(--ink);\n    font-family: \"Noto Sans JP\", \"Hiragino Sans\", \"Yu Gothic\", system-ui, sans-serif;\n    font-size: 14.5px;\n    line-height: 1.75;\n    padding-block: 0 80px;\n    padding-inline: 16px;\n  }\n  h1, h2, h3, h4 { font-family: \"Zen Kaku Gothic New\", \"Noto Sans JP\", system-ui, sans-serif; text-wrap: balance; margin: 0; }\n  code, .mono { font-family: \"IBM Plex Mono\", ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .92em; }\n  a { color: var(--accent); }\n  p { margin: 0; }\n\n  .wrap { max-width: 1180px; margin: 0 auto; }\n\n  /* ---------- header ---------- */\n  .masthead { padding-block: 40px 24px; border-bottom: 1px solid var(--line); }\n  .eyebrow { font-family: \"IBM Plex Mono\", monospace; font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); font-weight: 500; }\n  .masthead h1 { font-size: clamp(26px, 4vw, 38px); font-weight: 700; letter-spacing: -.01em; line-height: 1.25; margin-top: 8px; }\n  .lede { max-width: 66ch; color: var(--ink-2); margin-top: 12px; }\n  .meta { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 18px; font-size: 13px; color: var(--ink-2); }\n  .meta b { color: var(--ink); font-weight: 500; }\n\n  /* ---------- summary bar ---------- */\n  .tally {\n    position: sticky; top: 0; z-index: 5;\n    background: var(--surface); border: 1px solid var(--line); border-radius: 10px;\n    box-shadow: var(--shadow);\n    margin-top: 20px; padding: 10px 14px;\n    display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;\n  }\n  .tally .lab { font-size: 12px; color: var(--ink-3); letter-spacing: .06em; }\n  .tally .n { font-family: \"IBM Plex Mono\", monospace; font-size: 18px; font-weight: 500; font-variant-numeric: tabular-nums; }\n  .tally .n.ok { color: var(--accent); } .tally .n.ng { color: var(--bad); } .tally .n.hold { color: var(--warn); }\n  .bar { flex: 1 1 160px; height: 8px; border-radius: 99px; background: var(--surface-2); overflow: hidden; display: flex; }\n  .bar i { display: block; height: 100%; }\n  .bar .b-ok { background: var(--accent); } .bar .b-ng { background: var(--bad); } .bar .b-hold { background: var(--warn); }\n  .btn {\n    font: inherit; font-size: 13px; padding: 6px 12px; border-radius: 8px;\n    border: 1px solid var(--line); background: var(--surface); color: var(--ink); cursor: pointer;\n  }\n  .btn:hover { background: var(--surface-2); }\n  .btn:focus-visible, .res button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n\n  /* ---------- layout ---------- */\n  .grid { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 36px; margin-top: 28px; }\n  nav.toc { position: sticky; top: 76px; align-self: start; font-size: 13px; }\n  nav.toc ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }\n  nav.toc a { display: block; color: var(--ink-2); text-decoration: none; padding: 4px 10px; border-left: 2px solid var(--line-2); }\n  nav.toc a:hover { color: var(--ink); border-color: var(--accent); }\n  nav.toc .toc-h { font-size: 11px; letter-spacing: .1em; color: var(--ink-3); text-transform: uppercase; margin: 14px 0 6px 12px; }\n  @media (max-width: 860px) { .grid { grid-template-columns: 1fr; } nav.toc { position: static; } }\n\n  main { min-width: 0; display: flex; flex-direction: column; gap: 44px; }\n  section h2 { font-size: 22px; font-weight: 700; padding-bottom: 8px; border-bottom: 2px solid var(--ink); display: flex; align-items: baseline; gap: 12px; }\n  section h2 .id { font-family: \"IBM Plex Mono\", monospace; font-size: 13px; color: var(--accent); font-weight: 500; letter-spacing: .04em; }\n  section > p.intro { color: var(--ink-2); max-width: 70ch; margin-top: 12px; }\n  h3 { font-size: 16px; font-weight: 700; margin-top: 26px; }\n  h3 + p { color: var(--ink-2); max-width: 70ch; margin-top: 4px; }\n\n  /* ---------- info blocks ---------- */\n  .kv { display: grid; grid-template-columns: max-content 1fr; gap: 6px 18px; margin-top: 12px; font-size: 13.5px; }\n  .kv dt { color: var(--ink-3); } .kv dd { margin: 0; }\n  @media (max-width: 520px) { .kv { grid-template-columns: 1fr; gap: 2px; } .kv dt { margin-top: 8px; } }\n  .note { margin-top: 12px; padding: 10px 14px; border-left: 3px solid var(--accent); background: var(--accent-soft); border-radius: 0 8px 8px 0; font-size: 13.5px; }\n  .note.warn { border-color: var(--warn); background: var(--warn-soft); }\n  ul.plain { margin: 8px 0 0; padding-left: 1.2em; }\n  ul.plain li { margin: 2px 0; }\n\n  table.rules { border-collapse: collapse; width: 100%; margin-top: 12px; font-size: 13.5px; }\n  table.rules th, table.rules td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line-2); vertical-align: top; }\n  table.rules th { font-weight: 500; color: var(--ink-3); font-size: 12px; letter-spacing: .04em; }\n  table.rules td.num { text-align: right; font-variant-numeric: tabular-nums; font-family: \"IBM Plex Mono\", monospace; white-space: nowrap; }\n  .scroll { overflow-x: auto; }\n\n  /* ---------- flow diagram ---------- */\n  .flow { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }\n  .flow .step { flex: 1 1 150px; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font-size: 12.5px; position: relative; }\n  .flow .step b { display: block; font-size: 13px; color: var(--ink); }\n  .flow .step span { color: var(--ink-2); }\n  .flow .step .k { font-family: \"IBM Plex Mono\", monospace; font-size: 11px; color: var(--accent); }\n\n  /* ---------- test cases ---------- */\n  .cases { display: flex; flex-direction: column; gap: 10px; margin-top: 12px; }\n  .case { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px 12px; display: grid; grid-template-columns: 86px minmax(0, 1fr) auto; gap: 6px 14px; align-items: start; }\n  .case .cid { font-family: \"IBM Plex Mono\", monospace; font-size: 12.5px; color: var(--accent); font-weight: 500; padding-top: 3px; }\n  .case .pri { display: inline-block; margin-top: 4px; font-size: 10.5px; letter-spacing: .08em; padding: 1px 6px; border-radius: 4px; background: var(--surface-2); color: var(--ink-2); }\n  .case .pri.p1 { background: var(--bad-soft); color: var(--bad); }\n  .case .title { font-weight: 700; font-size: 14.5px; line-height: 1.5; }\n  .case .body { grid-column: 2; display: grid; grid-template-columns: 1fr 1fr; gap: 6px 20px; font-size: 13px; }\n  .case .body > div { min-width: 0; }\n  .case .body .l { font-size: 11px; letter-spacing: .08em; color: var(--ink-3); text-transform: uppercase; margin-bottom: 2px; }\n  .case .body ol, .case .body ul { margin: 0; padding-left: 1.3em; }\n  .case .body li { margin: 1px 0; }\n  .case .pre { grid-column: 1 / -1; color: var(--ink-2); }\n  .case .pre .l { display: inline; margin-right: 6px; }\n  .res { grid-column: 3; grid-row: 1 / span 2; display: flex; flex-direction: column; gap: 4px; }\n  .res button { font: inherit; font-size: 12px; padding: 3px 10px; border-radius: 6px; border: 1px solid var(--line); background: var(--surface); color: var(--ink-2); cursor: pointer; min-width: 58px; }\n  .res button[aria-pressed=\"true\"].ok { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }\n  .res button[aria-pressed=\"true\"].ng { background: var(--bad); color: #fff; border-color: var(--bad); }\n  .res button[aria-pressed=\"true\"].hold { background: var(--warn); color: #fff; border-color: var(--warn); }\n  .case.is-ok { border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); }\n  .case.is-ng { border-color: var(--bad); }\n  .case .memo { grid-column: 2 / -1; }\n  .case .memo input { width: 100%; font: inherit; font-size: 13px; padding: 5px 8px; border: 1px solid var(--line-2); border-radius: 6px; background: var(--surface-2); color: var(--ink); }\n  .case .memo input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }\n  @media (max-width: 640px) {\n    .case { grid-template-columns: 1fr; }\n    .case .body { grid-column: 1; grid-template-columns: 1fr; }\n    .res { grid-column: 1; grid-row: auto; flex-direction: row; }\n    .case .memo { grid-column: 1; }\n  }\n  @media (prefers-reduced-motion: no-preference) { .res button, .btn { transition: background .12s, color .12s; } }\n  @media print {\n    .tally, .res, .memo { display: none !important; }\n    .grid { grid-template-columns: 1fr; } nav.toc { display: none; }\n    .case { break-inside: avoid; }\n  }\n</style>\n\n<div class=\"wrap\">\n  <header class=\"masthead\">\n    <div class=\"eyebrow\">Test Specification · v1.8 · 2026-09-23</div>\n    <h1>SFA テスト仕様書</h1>\n    <p class=\"lede\">中小企業向け営業支援ツール「SFA」の受け入れテスト仕様。Web からの申し込みとテナントの自動作成、課金のルール、利用開始までの流れ、各機能の動作を、テスターが順に確認できるようにまとめています。各項目の右にある OK / NG / 保留 を押すと結果がこのブラウザに保存され、上部の集計に反映されます。v1.1 では、パスワード再設定、法務ページ、Gmail 以外のメールサーバー、担当者・取引先の付け替えと統合、フォーム通知の項目名設定の項目(ID の末尾が 07 以降と MS-04〜06)を追加しました。v1.4 では、行動の種類の設定(DL-06)、期限・日時の入力部品(DL-07)、タグの並び替え(MS-03)を追加し、DL-05 を新しい期限入力に合わせて修正しました。v1.5 では、取引先一覧からの複数統合(MS-07)と、フリーメールの相手の取引先判定(MS-08)を追加しました。v1.6 では、テンプレートを使わない差し込みと、画面が低いときの送信ボタン(MB-12)を追加しました。v1.7 では、メールのゴミ箱と一覧の「さらに表示」(MB-13)、タグ付けルールの「宛先」(MB-14)、メールアカウントでの絞り込み(MB-15)、アカウントごとの署名(MB-16)、運営管理のステップメール(AD-07)を追加しました。v1.8 では、ステップメールの送信元(AD-07 の手順 6)を追加しました。v1.9 では、行動(Todo)の担当者と行動一覧の担当者での絞り込み(DL-08)を追加しました。</p>\n    <div class=\"meta\">\n      <span>対象: <b>Next.js 16 + Supabase + Stripe(テストモード)</b></span>\n      <span>テスト環境: <b><a href=\"https://sfa.art-trading.net/login\">https://sfa.art-trading.net</a></b>(Vercel)</span>\n      <span>前提: <b>Stripe テストキー設定済み、運営側メールアカウント連携済み</b></span>\n    </div>\n    <div class=\"tally\" id=\"tally\">\n      <span class=\"lab\">進捗</span>\n      <span class=\"n\" id=\"t-done\">0</span><span class=\"lab\">/ <span id=\"t-total\">0</span> 件</span>\n      <span class=\"n ok\" id=\"t-ok\">0</span><span class=\"lab\">OK</span>\n      <span class=\"n ng\" id=\"t-ng\">0</span><span class=\"lab\">NG</span>\n      <span class=\"n hold\" id=\"t-hold\">0</span><span class=\"lab\">保留</span>\n      <div class=\"bar\"><i class=\"b-ok\" id=\"b-ok\"></i><i class=\"b-ng\" id=\"b-ng\"></i><i class=\"b-hold\" id=\"b-hold\"></i></div>\n      <button class=\"btn\" id=\"copy\">結果をコピー</button>\n      <button class=\"btn\" id=\"reset\">結果をクリア</button>\n    </div>\n  </header>\n\n  <div class=\"grid\">\n    <nav class=\"toc\" aria-label=\"目次\">\n      <div class=\"toc-h\">準備</div>\n      <ol>\n        <li><a href=\"#env\">0. テスト環境と準備</a></li>\n      </ol>\n      <div class=\"toc-h\">シナリオ</div>\n      <ol>\n        <li><a href=\"#signup\">1. 申し込みとテナント自動作成</a></li>\n        <li><a href=\"#onboard\">2. 利用開始</a></li>\n        <li><a href=\"#billing\">3. 課金のルール</a></li>\n      </ol>\n      <div class=\"toc-h\">機能</div>\n      <ol>\n        <li><a href=\"#inbox\">4. メール</a></li>\n        <li><a href=\"#inquiry\">5. 問い合わせ</a></li>\n        <li><a href=\"#deals\">6. 案件と売上</a></li>\n        <li><a href=\"#master\">7. 取引先・担当者・タグ</a></li>\n        <li><a href=\"#members\">8. 営業担当者</a></li>\n        <li><a href=\"#settings\">9. 設定とログ</a></li>\n        <li><a href=\"#admin\">10. 運営管理</a></li>\n        <li><a href=\"#isolation\">11. テナント分離と権限</a></li>\n      </ol>\n    </nav>\n\n    <main>\n      <!-- ===================== 0 ===================== -->\n      <section id=\"env\">\n        <h2><span class=\"id\">§0</span>テスト環境と準備</h2>\n        <p class=\"intro\">テストは本番 URL <code>https://sfa.art-trading.net</code> で行います(Stripe はテストモードのため実際の請求は発生しません)。画面の指示にあるパス(/signup など)はこの URL の配下です。以下をそろえてから開始してください。</p>\n        <dl class=\"kv\">\n          <dt>テスト用メール</dt><dd>申し込み用に、まだこのシステムに登録されていないメールアドレスを 2 つ(会社 A 用・会社 B 用)。自社ドメインのエイリアス(<code>name+testa@…</code>)で可。</dd>\n          <dt>Gmail 連携用</dt><dd>受信テスト用の Gmail アカウントとアプリパスワード(<a href=\"https://myaccount.google.com/apppasswords\" target=\"_blank\" rel=\"noreferrer\">myaccount.google.com/apppasswords</a>)。</dd>\n          <dt>Stripe テストカード</dt><dd>成功: <code>4242 4242 4242 4242</code> / 拒否: <code>4000 0000 0000 0002</code> / 有効期限は未来の任意、CVC 任意、郵便番号任意。</dd>\n          <dt>運営アカウント</dt><dd>運営管理 <code>https://sfa.art-trading.net/admin</code> にログインできるスーパーユーザー(akfujii@art-trading.co.jp)。</dd>\n          <dt>Stripe ダッシュボード</dt><dd>テストモードで顧客・サブスクリプション・Webhook の配信状況を確認できること。</dd>\n        </dl>\n        <div class=\"note\">\n          <b>結果の判定基準:</b> 期待結果がすべて満たされれば OK。ひとつでも違えば NG にし、メモ欄に画面のメッセージをそのまま書いてください。環境の都合で実施できない場合は保留。\n        </div>\n        <div class=\"note warn\">\n          <b>お試し期限切れの再現:</b> お試し期間は 90 日なので、期限切れの動作は運営管理 → テナント詳細 → 契約・上限・課金状態の「お試し期限」を過去の日付に変えて再現します(テスト後に戻すこと)。\n        </div>\n      </section>\n\n      <!-- ===================== 1 ===================== -->\n      <section id=\"signup\">\n        <h2><span class=\"id\">§1</span>申し込みとテナント自動作成</h2>\n        <p class=\"intro\">Web の申し込みフォームから、運営の手を介さずに会社(テナント)が作られるまで。カードの登録は不要で、90 日間のお試しが自動で始まります。</p>\n        <div class=\"flow\">\n          <div class=\"step\"><span class=\"k\">https://sfa.art-trading.net/signup</span><b>申し込みフォーム</b><span>会社名・会社 ID・担当者・メール</span></div>\n          <div class=\"step\"><span class=\"k\">mail</span><b>確認メール</b><span>運営側 Gmail から 24 時間有効のリンク</span></div>\n          <div class=\"step\"><span class=\"k\">/signup/verify</span><b>内容確認</b><span>「アカウントを開設する」ボタン</span></div>\n          <div class=\"step\"><span class=\"k\">create_tenant</span><b>テナント作成</b><span>お試し 90 日、上限は運営の既定値</span></div>\n          <div class=\"step\"><span class=\"k\">/set-password</span><b>パスワード設定</b><span>そのままログイン状態に</span></div>\n        </div>\n\n        <h3>入力ルール</h3>\n        <table class=\"rules\">\n          <thead><tr><th>項目</th><th>ルール</th></tr></thead>\n          <tbody>\n            <tr><td>会社 ID</td><td>英小文字・数字・ハイフン、3〜40 文字、先頭と末尾は英数字。会社名からの自動提案あり。既存テナントと重複不可。後から変更不可。</td></tr>\n            <tr><td>メールアドレス</td><td>既にログインできる利用者のアドレスは不可(別テナントに所属しているため)。</td></tr>\n            <tr><td>連投の抑制</td><td>同じメールアドレスは 24 時間に 3 回まで。同じ IP は 1 時間に 10 回まで。</td></tr>\n            <tr><td>確認リンク</td><td>有効期限 24 時間。1 回使うと無効。リンクを開いただけではテナントは作られない(ボタンを押した時点で作成)。</td></tr>\n          </tbody>\n        </table>\n\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"SU-01\"><div><div class=\"cid\">SU-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">正常な申し込みで確認メールが届く</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>未登録のメールアドレス(会社 A 用)を用意。</div>\n              <div><div class=\"l\">手順</div><ol><li>ログイン画面の「無料で申し込む」を開く</li><li>会社名「テスト商事 A」を入力し、会社 ID が自動提案されることを確認</li><li>会社 ID を <code>test-a-〔日付〕</code> に変更</li><li>担当者名・メール・電話(任意)を入力、同意にチェック</li><li>「確認メールを送る」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「確認メールを送りました」の画面に切り替わり、送信先アドレスが表示される</li><li>数分以内に【SFA】お申し込みの確認 というメールが運営側の Gmail から届く</li><li>本文に会社名・担当者名とリンクが差し込まれている</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ(NG の場合はメッセージを転記)\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-02\"><div><div class=\"cid\">SU-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">確認リンクからテナントが自動作成され、パスワード設定に進む</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>SU-01 のメールを受信済み。</div>\n              <div><div class=\"l\">手順</div><ol><li>メールのリンクを開く</li><li>会社名・会社 ID・担当者・メールが表示されることを確認</li><li>「アカウントを開設する」を押す</li><li>パスワード(8 文字以上)を設定</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>ボタンを押す前はテナントが作られていない(運営管理の一覧に無い)</li><li>押すとパスワード設定画面に遷移し、設定後にダッシュボードが開く</li><li>設定 → 会社(テナント)に会社名・会社 ID・「お試し期間」と 90 日後の期限が表示される</li><li>運営管理のテナント一覧に「Web 申し込み」経路で追加され、上限がユーザー 1 / メールアカウント 1 / 1GB になっている</li><li>運営の通知先メールに「新規申し込み」の通知が届く</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-03\"><div><div class=\"cid\">SU-03</div><span class=\"pri\">通常</span></div><div class=\"title\">使用済み・期限切れのリンクは拒否される</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>SU-02 で使ったリンクをもう一度開く</li><li>URL の token を適当に書き換えて開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>どちらも「リンクが無効です」と表示され、ログインと再申し込みへの案内が出る</li><li>テナントが二重に作られない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-04\"><div><div class=\"cid\">SU-04</div><span class=\"pri\">通常</span></div><div class=\"title\">会社 ID の形式と重複の検証</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>会社 ID に「ab」(2 文字)、「-abc」、「ABC 商事」を入れて送信</li><li>SU-02 で作った会社 ID をそのまま入れて送信</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>形式違反は送信前にブラウザの検証で止まるか、「英小文字・数字・ハイフンで 3〜40 文字」のエラーが出る</li><li>重複は「この会社 ID は既に使われています」と表示され、入力内容は保持される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-05\"><div><div class=\"cid\">SU-05</div><span class=\"pri\">通常</span></div><div class=\"title\">登録済みメールアドレスでは申し込めない</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>SU-02 でログインできるようになったアドレスで、別の会社名・会社 ID で申し込む</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「このメールアドレスは既に登録されています。ログイン画面からログインしてください」と表示される</li><li>確認メールは送られない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-06\"><div><div class=\"cid\">SU-06</div><span class=\"pri\">任意</span></div><div class=\"title\">同じメールアドレスからの連投は 1 日 3 回まで</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>未登録アドレスで申し込みを 4 回続けて送る(会社 ID は毎回変える)</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>3 回目までは確認メールが届く</li><li>4 回目は「本日の上限に達しました」と表示される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-08\"><div><div class=\"cid\">SU-08</div><span class=\"pri p1\">必須</span></div><div class=\"title\">法務ページ(利用規約・プライバシーポリシー・特定商取引法)の表示</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>未ログインのブラウザで <code>https://sfa.art-trading.net/legal/terms</code>、<code>https://sfa.art-trading.net/legal/privacy</code>、<code>https://sfa.art-trading.net/legal/tokushoho</code> を開く</li><li>ログイン画面と申し込み画面の下部リンクから各ページへ移動</li><li>運営管理 → 料金・既定値で基本料金を変更し、特定商取引法のページを再読み込み(確認後に戻す)</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>3 ページともログインなしで開け、ヘッダー・フッターのリンクで相互に移動できる</li><li>特定商取引法のページに事業者名(アートトレーディング株式会社)、代表者、住所、電話、メール、料金(税抜・税込)、お試し期間、解約とデータ削除の扱いが表示される</li><li>料金の変更が特定商取引法のページに反映される</li><li>プライバシーポリシーに委託先(Supabase・Vercel・Stripe・Anthropic・Google)と、データベースは東京リージョンに保管する旨がある</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-09\"><div><div class=\"cid\">SU-09</div><span class=\"pri\">通常</span></div><div class=\"title\">申し込みの同意チェック(規約・ポリシーへのリンク)</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>申し込み画面で同意チェックの文中の「利用規約」「プライバシーポリシー」を押す</li><li>チェックを外したまま送信する</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>リンクは別タブで各ページを開く</li><li>文言に「お試し期間の終了と同時にデータが削除される」旨が含まれる</li><li>未チェックはブラウザの必須チェックで止まるか、「利用規約とプライバシーポリシーへの同意が必要です」のエラーになる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"SU-07\"><div><div class=\"cid\">SU-07</div><span class=\"pri\">通常</span></div><div class=\"title\">申し込み画面の料金表示</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>PC 幅で /signup を開き、左側の料金表を確認</li><li>運営管理 → 料金・既定値で基本料金を変更して再読み込み</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>基本料金(税抜と税込)、ユーザー追加、メールアカウント追加、お試し日数が運営の設定と一致する</li><li>「表示価格は税抜、請求時に消費税 10% を加算」の注記がある</li><li>変更後に元の値へ戻す</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 2 ===================== -->\n      <section id=\"onboard\">\n        <h2><span class=\"id\">§2</span>利用開始</h2>\n        <p class=\"intro\">開設直後の会社が、メールアカウントを連携してメールを取り込み、同僚を招待するまで。ログインは招待制で、自己登録はできません。パスワードを忘れたときは再設定メールで復旧します。</p>\n\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"ON-01\"><div><div class=\"cid\">ON-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">ログインとログアウト</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>ログアウトし、SU-02 のメールとパスワードでログイン</li><li>間違ったパスワードでログイン</li><li>ログイン状態で /login を直接開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>正しい認証情報でダッシュボードが開き、ヘッダーに会社名が出る</li><li>誤りはエラーメッセージが出て入力画面に留まる</li><li>ログイン中に /login を開くとダッシュボードへ戻される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-02\"><div><div class=\"cid\">ON-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">未ログインでは業務画面を開けない</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>ログアウトした状態で /inbox、/deals、/settings/billing を直接開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>いずれもログイン画面へリダイレクトされ、ログイン後に元のページへ戻る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-03\"><div><div class=\"cid\">ON-03</div><span class=\"pri p1\">必須</span></div><div class=\"title\">Gmail アカウントの連携と初回同期</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>テスト用 Gmail とアプリパスワード。受信トレイに数通のメールがあること。</div>\n              <div><div class=\"l\">手順</div><ol><li>設定 → 「メールアカウントを追加」で「Gmail / Google Workspace」を選び、メールアドレスとアプリパスワードを登録</li><li>接続テストを実行</li><li>「今すぐ同期」を押す</li><li>メール一覧を開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>接続テストが成功し、「既定の差出人」バッジと「Gmail / Google Workspace」の表示が付く</li><li>同期後に最終同期日時が表示され、受信メールと送信済みメールが一覧に入る</li><li>差出人が担当者・取引先として自動登録される(担当者一覧で確認)</li><li>誤ったアプリパスワードでは接続テストが失敗し、原因が分かるメッセージが出る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-04\"><div><div class=\"cid\">ON-04</div><span class=\"pri p1\">必須</span></div><div class=\"title\">同僚を招待してログインできるようにする</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>運営管理でこの会社のユーザー上限を 2 に上げておく(既定は 1 で招待不可)。</div>\n              <div><div class=\"l\">手順</div><ol><li>営業担当者 → 追加でメールアドレス付きの担当者を作る</li><li>「招待」を押す</li><li>届いた招待メールのリンクからパスワードを設定</li><li>別ブラウザでその人としてログイン</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>招待メールは自社(会社 A)の Gmail から送られ、招待者名が入っている</li><li>担当者の状態が「招待中」→ ログイン後に「ログイン可」に変わる</li><li>営業担当者ページの「N / 上限」が 2 / 2 になる</li><li>その人は同じ会社のデータだけが見える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-05\"><div><div class=\"cid\">ON-05</div><span class=\"pri\">通常</span></div><div class=\"title\">ユーザー上限に達すると招待できない</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>ON-04 の状態(2 / 2)でさらに担当者を追加して「招待」</li><li>招待済みの担当者に「再送」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>新規招待は「ログインユーザー数の上限(2 名、招待中を含む)に達しています」で止まる</li><li>再送は枠を消費せず送れる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-07\"><div><div class=\"cid\">ON-07</div><span class=\"pri p1\">必須</span></div><div class=\"title\">パスワードの再設定</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>SU-02 のアカウント(会社 A)でログアウト済み。</div>\n              <div><div class=\"l\">手順</div><ol><li>ログイン画面の「パスワードを忘れた方」を開き、SU-02 のメールアドレスを送信</li><li>未登録のアドレスでも送信</li><li>届いたメールのリンクを開き、新しいパスワードを設定</li><li>古いパスワードと新しいパスワードでそれぞれログイン</li><li>使用済みのリンクをもう一度開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>登録あり・なしのどちらも「登録されていれば再設定メールを送りました」の同じ文言になる(登録の有無が分からない)</li><li>【SFA】パスワード再設定のご案内 が会社 A の既定メールアカウント(無ければ運営側)から届く</li><li>リンク先は「新しいパスワードを設定」の画面で、設定後にダッシュボードが開く</li><li>古いパスワードは拒否され、新しいパスワードでログインできる</li><li>使用済みリンクは「パスワード再設定のリンクが無効か、有効期限が切れています」のログイン画面になる</li><li>同じアドレスに 4 回続けて送ると、4 回目はメールが届かない(画面の文言は同じ)</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-08\"><div><div class=\"cid\">ON-08</div><span class=\"pri p1\">必須</span></div><div class=\"title\">Gmail 以外の IMAP / SMTP サーバーの連携</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>レンタルサーバーなど、IMAP と SMTP が使えるメールアカウントとその設定値。メールアカウント上限 2 以上。</div>\n              <div><div class=\"l\">手順</div><ol><li>「メールアカウントを追加」で「その他の IMAP / SMTP サーバー」を選ぶ</li><li>IMAP サーバー:993、SMTP サーバー:465(または 587)、必要ならログイン ID を入力して保存</li><li>接続テスト → 今すぐ同期</li><li>そのアカウントを差出人にしてメールを送信</li><li>SMTP ポートを 25 や暗号化なしの設定にして接続テスト</li><li>サーバー名に URL(https://…)を入れて保存</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>設定一覧に「その他の IMAP / SMTP サーバー · IMAP ホスト:ポート / SMTP ホスト:ポート」とログイン ID が表示される</li><li>接続テストが成功し、受信トレイと送信済み(Sent / Sent Items / 送信済み などの名前でも)が取り込まれる</li><li>587 は STARTTLS で送信できる。暗号化に対応しないポートは接続テストが失敗し、原因の分かるメッセージが出る</li><li>URL 形式のサーバー名は「ホスト名だけを入力してください」で保存できない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-09\"><div><div class=\"cid\">ON-09</div><span class=\"pri p1\">必須</span></div><div class=\"title\">メール転送で受信 + SMTP で送信</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>運営側で転送メールの受信用メールボックス(環境変数 INBOUND_*)を設定済み。自動転送を設定できるメールアドレスと、その SMTP の設定値。メールアカウント上限 2 以上。</div>\n              <div><div class=\"l\">手順</div><ol><li>「メールアカウントを追加」で「メール転送で受信 + SMTP で送信」を選び、メールアドレスと SMTP サーバー・ポート・パスワードを入力して保存</li><li>表示された受け口アドレスをコピーし、メールサーバーで自動転送を設定(サーバーに残す)</li><li>転送を設定する前に「届いたか確認する」を押す</li><li>外部のアドレスからそのメールアドレス宛てにメールを送り、「届いたか確認する」を押す</li><li>メール一覧で届いたメールを開き、返信する</li><li>普段のメールソフトから、受け口アドレスを BCC に入れて顧客宛てに送信し、「今すぐ同期」</li><li>メールソフトの「転送」ボタンで、顧客からのメールを受け口アドレスに転送し、「今すぐ同期」</li><li>「アドレスを再発行」を実行し、古いアドレス宛てに送って「今すぐ同期」</li><li>接続テストを実行</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>IMAP の欄が出ず、保存するとダイアログが「次に、メールの転送を設定してください」に切り替わる(SMTP の確認結果、受け口アドレス、サービス別の手順)</li><li>転送前は「まだ届いていません」、転送後は「n 通届いています」になり、一覧の行が「転送待ち」から「受信中」に変わる</li><li>届いたメールの差出人は元の送信者で、担当者・取引先が自動登録される。返信はそのアカウントの SMTP から送られる</li><li>BCC で送ったメールは送信メールとして記録される</li><li>手動転送(Fwd:)は本文の差出人が相手として登録される</li><li>再発行後、古いアドレス宛てのメールは取り込まれない</li><li>接続テストは「SMTP に接続できました」になる(IMAP は確認しない)</li><li>運営側の設定が無い環境では、選択肢に「メール転送で受信」が出ない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ON-06\"><div><div class=\"cid\">ON-06</div><span class=\"pri\">通常</span></div><div class=\"title\">営業担当者の削除でログインが無効になり枠が空く</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>ON-04 で招待した人を削除</li><li>その人のブラウザで画面を操作</li><li>自分自身を削除しようとする</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>削除後、その人は次の操作でログイン画面に戻され、再ログインできない</li><li>「N / 上限」が 1 / 2 に戻る</li><li>自分自身は「削除できません」のメッセージ</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 3 ===================== -->\n      <section id=\"billing\">\n        <h2><span class=\"id\">§3</span>課金のルール</h2>\n        <p class=\"intro\">料金は上限ではなく実際の利用数で毎月計算し、Stripe のサブスクリプション数量に自動で反映します。お試し中はカード不要、期限が切れると閲覧のみになります。</p>\n\n        <h3>料金の計算</h3>\n        <p>基本料金にメールアカウント 1 件・ユーザー 1 名(招待中を含む)・容量 1GB が含まれ、超えた分がオプション料金になります。消費税 10% は外税で、円未満は切り捨てです。</p>\n        <div class=\"scroll\"><table class=\"rules\">\n          <thead><tr><th>項目</th><th>単価(税抜)</th><th>数え方</th></tr></thead>\n          <tbody>\n            <tr><td>基本料金</td><td class=\"num\">10,000 円/月</td><td>常に 1</td></tr>\n            <tr><td>ユーザー追加</td><td class=\"num\">1,000 円/名</td><td>ログインできる利用者 + 招待中 − 1</td></tr>\n            <tr><td>メールアカウント追加</td><td class=\"num\">5,000 円/件</td><td>連携メールアカウント数 − 1</td></tr>\n            <tr><td>容量追加</td><td class=\"num\">0 円/GB</td><td>使用容量を GB に切り上げ − 1(単価 0 のため Stripe には載らない)</td></tr>\n          </tbody>\n        </table></div>\n        <div class=\"note\"><b>検算例:</b> ユーザー 3 名、メールアカウント 2 件 → 10,000 + 2 × 1,000 + 1 × 5,000 = <b>17,000 円</b>、消費税 1,700 円、税込 <b>18,700 円</b>。</div>\n\n        <h3>契約状態の遷移</h3>\n        <p>Stripe からの Webhook で、テナントの契約状態と課金状態が自動更新されます。</p>\n        <div class=\"scroll\"><table class=\"rules\">\n          <thead><tr><th>Stripe の状態</th><th>契約状態</th><th>課金状態</th><th>利用</th></tr></thead>\n          <tbody>\n            <tr><td>(未登録)</td><td>お試し期間</td><td>お試し中</td><td>期限内は利用可、期限後は閲覧のみ</td></tr>\n            <tr><td>trialing</td><td>お試し期間</td><td>お試し中</td><td>利用可(カード登録済み、期限は Stripe と同期)</td></tr>\n            <tr><td>active</td><td>契約中</td><td>課金中</td><td>利用可</td></tr>\n            <tr><td>past_due</td><td>契約中</td><td>支払い遅延</td><td>利用可(警告表示、Stripe が再試行)</td></tr>\n            <tr><td>unpaid / paused</td><td>停止中</td><td>支払い遅延</td><td>閲覧のみ</td></tr>\n            <tr><td>canceled</td><td>解約</td><td>解約済み</td><td>閲覧のみ、「再開する」ボタン</td></tr>\n          </tbody>\n        </table></div>\n        <div class=\"note warn\">運営が手で「停止中」にしたテナントは、Stripe の状態で上書きされません(運営の停止が優先)。</div>\n\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"BL-01\"><div><div class=\"cid\">BL-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">ご契約・お支払い画面の料金内訳</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>会社 A: ユーザー 2 名(招待中を含む)、メールアカウント 1 件。</div>\n              <div><div class=\"l\">手順</div><ol><li>設定 → 「ご契約・お支払い」を開く</li><li>Gmail アカウントをもう 1 件追加して再表示</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>基本 10,000 + ユーザー追加 1 × 1,000 = 小計 11,000、消費税 1,100、合計 12,100 円</li><li>メールアカウント追加後は 5,000 円増え、小計 16,000、税込 17,600 円</li><li>お試しの残り日数と期限、ご利用状況(N / 上限)が表示される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-02\"><div><div class=\"cid\">BL-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">お試し中にカードを登録すると、課金開始がお試し終了日になる</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>お試し残り 2 日以上。Stripe テストモード。</div>\n              <div><div class=\"l\">手順</div><ol><li>「お支払い方法を登録して契約する」を押す</li><li>Stripe Checkout で 4242… のカードを入力して登録</li><li>戻った画面と Stripe ダッシュボードを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>Checkout は日本語表示で、明細に基本料金と追加分、消費税 10% が載る</li><li>戻ると「お支払い方法を登録しました」と出て、契約状態は「お試し期間」のまま、「お支払い方法は登録済み。お試し終了後に自動課金」の説明になる</li><li>Stripe のサブスクリプションが trialing で、トライアル終了日がテナントのお試し期限と一致</li><li>顧客のメタデータに tenant_id と会社 ID が入っている</li><li>「お支払い方法・請求書を管理」ボタンが表示される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-03\"><div><div class=\"cid\">BL-03</div><span class=\"pri p1\">必須</span></div><div class=\"title\">お試し期限切れで閲覧のみになり、カード登録で復帰する</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>会社 B(カード未登録)。運営管理でお試し期限を昨日に変更。</div>\n              <div><div class=\"l\">手順</div><ol><li>会社 B でログインして各画面を開く</li><li>取引先の追加、メール送信、同期を試す</li><li>バナーのリンクから「ご契約・お支払い」→ カード登録</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>上部に「お試し期間が終了しました…閲覧のみ」のバナーとご契約・お支払いへのリンク。ご契約・お支払い画面には「登録がない場合、利用規約にもとづきデータは削除されます」の案内</li><li>書き込み操作はすべて「お試し期間が終了しました」のエラーで止まる。閲覧はできる</li><li>カード登録後は即時課金され、契約状態が「契約中」、課金状態が「課金中」になり、バナーが消えて操作できる</li><li>次回請求日が表示される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-04\"><div><div class=\"cid\">BL-04</div><span class=\"pri\">通常</span></div><div class=\"title\">お試し終了 7 日前からの案内バナー</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>カード未登録の会社。運営管理でお試し期限を 5 日後に変更。</div>\n              <div><div class=\"l\">手順</div><ol><li>その会社でログイン</li><li>カードを登録して再表示</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「お試し期間はあと 5 日で終了します」の青いバナーとリンクが出る</li><li>カード登録後はバナーが消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-05\"><div><div class=\"cid\">BL-05</div><span class=\"pri p1\">必須</span></div><div class=\"title\">利用数の変化が Stripe の数量に自動反映される</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>契約中(または trialing)の会社。ユーザー上限 3、メールアカウント上限 2。</div>\n              <div><div class=\"l\">手順</div><ol><li>営業担当者を招待する</li><li>Gmail アカウントを追加する</li><li>Stripe ダッシュボードでサブスクリプションの明細を確認</li><li>招待した担当者を削除、Gmail アカウントを削除して再確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>招待後に「ユーザー追加」の数量が 1 増え、アカウント追加後に「メールアカウント追加」の明細が数量 1 で加わる(反映は数秒〜1 分)</li><li>削除後は数量が減り、0 になった明細は消える</li><li>日割り(proration)の明細が次回請求に入る</li><li>失敗した場合は設定 → システムログに stripe.sync のエラーが残る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-06\"><div><div class=\"cid\">BL-06</div><span class=\"pri p1\">必須</span></div><div class=\"title\">カスタマーポータルで支払い方法の変更・請求書・解約</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「お支払い方法・請求書を管理」を押す</li><li>カードを別のテストカードに変更</li><li>請求書一覧を開く</li><li>「サブスクリプションをキャンセル」(期間末)を実行して戻る</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>Stripe のポータルが日本語で開き、戻るとご契約・お支払い画面に戻る</li><li>解約予約後、画面に「〔日付〕で解約する予定」の注意が出る。契約状態は「契約中」のまま</li><li>ポータルで解約を取り消すと注意が消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-07\"><div><div class=\"cid\">BL-07</div><span class=\"pri\">通常</span></div><div class=\"title\">支払い失敗時の表示と通知</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>Stripe ダッシュボード(テスト)で、対象サブスクリプションの支払い方法を「請求が失敗するカード(4000 0000 0000 0341)」に変えるか、テストクロックで請求を進める。</div>\n              <div><div class=\"l\">手順</div><ol><li>Stripe で請求書の支払いを失敗させる</li><li>テナント側のご契約・お支払い画面と、運営の通知先メールを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>課金状態が「支払い遅延」になり、画面に黄色の警告(カード情報の確認案内)が出る。操作はまだできる</li><li>運営に「お支払いに失敗しました」の通知メールが届き、システムログに stripe.payment_failed が残る</li><li>Stripe 側で最終的に unpaid になると契約状態が「停止中」になり閲覧のみになる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-08\"><div><div class=\"cid\">BL-08</div><span class=\"pri\">通常</span></div><div class=\"title\">解約後の閲覧のみと再開</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>Stripe ダッシュボードでサブスクリプションを即時キャンセル。</div>\n              <div><div class=\"l\">手順</div><ol><li>テナント側で画面を開く</li><li>「お支払い方法を登録して再開する」から再度 Checkout</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>契約状態「解約」、バナー「解約済みです。データの閲覧のみ可能」、書き込みは拒否</li><li>再開の Checkout 後に「契約中」に戻り操作できる。Stripe には新しいサブスクリプションができる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-09\"><div><div class=\"cid\">BL-09</div><span class=\"pri\">通常</span></div><div class=\"title\">Webhook の重複配信と署名検証</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>Stripe ダッシュボード → Webhooks で直近のイベントを「再送信」</li><li>署名なしで <code>/api/stripe/webhook</code> に POST する(curl 等)</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>再送は 200 で応答し、テナントの状態は変わらない(重複として無視)</li><li>署名なしは 400 で拒否され、システムログに warn が残る(通知メールは飛ばない)</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-10\"><div><div class=\"cid\">BL-10</div><span class=\"pri\">通常</span></div><div class=\"title\">運営の料金変更が新しい契約と数量同期に反映される</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>運営管理 → 料金・既定値でユーザー追加単価を 1,500 円に変更</li><li>契約中の会社で営業担当者を招待(数量同期を発生させる)</li><li>Stripe の明細を確認し、単価を 1,000 円に戻す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「ユーザー追加」の明細が 1,500 円の新しい価格に置き換わる(旧価格の明細は消える)</li><li>Stripe の商品は増えず、価格(Price)だけが増える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"BL-11\"><div><div class=\"cid\">BL-11</div><span class=\"pri\">任意</span></div><div class=\"title\">Stripe 未設定時の表示</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>プレビュー環境などで STRIPE_SECRET_KEY を外した環境がある場合のみ。</div>\n              <div><div class=\"l\">手順</div><ol><li>ご契約・お支払いを開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「オンラインでのお支払い登録は準備中です」と表示され、ボタンが出ない</li><li>申し込みは通常どおり動く</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 4 ===================== -->\n      <section id=\"inbox\">\n        <h2><span class=\"id\">§4</span>メール</h2>\n        <p class=\"intro\">連携したメールアカウントから取り込んだメールの閲覧、返信・新規作成、問い合わせ登録、タグ付け、担当者・取引先の付け替え。返信は受信したアカウントから送られます。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"MB-01\"><div><div class=\"cid\">MB-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">受信トレイの表示と既読管理</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>メール一覧で未読メールを確認</li><li>1 通開いてスレッドを表示</li><li>一覧に戻る</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>未読は太字とドットで区別され、サイドメニューの「メール」に未読数バッジが出る</li><li>開くと既読になりバッジが減る</li><li>スレッドは日時順に並び、自分の送信メールは区別して表示される</li><li>日時は日本時間</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-02\"><div><div class=\"cid\">MB-02</div><span class=\"pri\">通常</span></div><div class=\"title\">検索(送信者・件名・本文)と未読絞り込み</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>検索対象を「件名」にして既知の語で検索ボタン</li><li>「本文」「送信者」でも同様に</li><li>「未読」フィルタを切り替える</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>対象に応じて一致するメールだけが残る</li><li>該当なしの場合は空の案内が出る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-03\"><div><div class=\"cid\">MB-03</div><span class=\"pri p1\">必須</span></div><div class=\"title\">返信(署名・件名・差出人アカウント)</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>設定 → 署名に会社名などを入れておく。</div>\n              <div><div class=\"l\">手順</div><ol><li>受信メールを開いて返信フォームを表示</li><li>本文に署名が初期表示されることを確認し、送信</li><li>相手側の受信と、スレッドへの追加を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>署名は「会社名・担当者名・メールアドレス・追記」の順で入り、担当者名はログイン中の営業担当者名</li><li>送信後にスレッドに自分の返信が付き、Gmail の送信済みにも残る</li><li>差出人は受信したアカウント</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-04\"><div><div class=\"cid\">MB-04</div><span class=\"pri p1\">必須</span></div><div class=\"title\">新規作成と添付ファイル(ドラッグ&ドロップ)</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「新規作成」で宛先を複数(カンマ区切り)入力</li><li>ファイルを選択で 1 件、ドラッグ&ドロップで 1 件添付</li><li>送信し、受信側で添付を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>添付欄に 2 件表示され、削除もできる</li><li>受信側に添付付きで届く</li><li>送信したメールが一覧に「送信」として残り、添付をダウンロードできる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-05\"><div><div class=\"cid\">MB-05</div><span class=\"pri\">通常</span></div><div class=\"title\">受信添付の保存と容量上限</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>運営管理でこの会社の容量上限を小さく(例: 0.01GB)して、大きめの添付を送る。</div>\n              <div><div class=\"l\">手順</div><ol><li>テスト Gmail 宛に添付付きメールを送り、同期</li><li>設定 → 会社(テナント)の使用容量を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>上限内なら添付が一覧に表示されダウンロードできる</li><li>上限を超える添付は保存されず、システムログに容量超過が記録される(メール本文は取り込まれる)</li><li>テスト後に上限を戻す</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-06\"><div><div class=\"cid\">MB-06</div><span class=\"pri\">通常</span></div><div class=\"title\">自社サイトのフォーム通知メールの扱い(推奨フォーマット)</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>設定 → 「問い合わせフォームの通知メール」の推奨フォーマット(会社名: / お名前: / メールアドレス: / 電話番号: / お問い合わせ内容:)で書いた本文を、フォームツール役の別アドレスから連携アカウント宛に送る。</div>\n              <div><div class=\"l\">手順</div><ol><li>フォーム通知メールを同期</li><li>担当者一覧と、そのメールの返信フォームを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>送信元ではなく本文の問い合わせ者(会社名・氏名・メール・電話)が担当者・取引先として登録される</li><li>返信の宛先が問い合わせ者になり、件名が設定の「返信件名」になる</li><li>問い合わせに登録すると、要約と分類(見積依頼など)が本文の内容から付く</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-07\"><div><div class=\"cid\">MB-07</div><span class=\"pri\">通常</span></div><div class=\"title\">選択してタグ付け・一括削除</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>メールを 2 通選択して「タグ」から「リード」を付ける</li><li>スレッド内の他のメールと、紐付く担当者のタグを確認</li><li>タグで検索し、選択して削除(確認ダイアログ)</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>タグはスレッド内の全メールと担当者にも付く</li><li>削除はスレッド単位で消え、件数がトーストに出る</li><li>削除したメールは次回同期で再取り込みされない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-09\"><div><div class=\"cid\">MB-09</div><span class=\"pri p1\">必須</span></div><div class=\"title\">スレッドの担当者・取引先の付け替え</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>担当者・取引先が付いたスレッドが 2 つ以上あり、そのうち 1 つは問い合わせ登録済みで、別の取引先の案件に紐付いている。</div>\n              <div><div class=\"l\">手順</div><ol><li>スレッド画面の「担当者・取引先を変更」→「登録済みの担当者を選ぶ」で別の会社の担当者を検索して選び、変更</li><li>問い合わせページと、元の案件の「メール履歴」を確認</li><li>同じダイアログで「新しい担当者を登録する」→ 氏名・メール・「新しい取引先を登録する」で会社名を入れて変更</li><li>既存担当者と同じメールアドレスで「新しい担当者を登録する」</li><li>「取引先だけを指定する」と「紐付けを外す」も実行</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>関連情報の取引先・担当者が変わり、スレッド内の全メールに反映される(取引先詳細の「メール」タブで確認)</li><li>そのメールから登録した問い合わせの取引先・担当者も変わる</li><li>別の取引先の案件への紐付けは外れる(案件のメール履歴から消える)</li><li>新しい担当者・取引先が作られ、担当者一覧・取引先一覧に出る</li><li>重複するメールアドレスは「既に登録されています。一覧から選んでください」で止まる</li><li>「紐付けを外す」後は取引先・担当者が「未登録」になり、担当者・取引先そのものは残る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-10\"><div><div class=\"cid\">MB-10</div><span class=\"pri\">通常</span></div><div class=\"title\">フォーム通知の項目名と送信元の設定</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>MB-06 と同じ送り方で、項目名を「貴社名(必須):」「ご担当者様:」「連絡先メール:」のように標準に無いものにした通知メールを用意。</div>\n              <div><div class=\"l\">手順</div><ol><li>設定なしで同期し、担当者一覧を確認</li><li>設定 → 問い合わせフォームの通知メールで、氏名の項目名に「ご担当者様」、メールアドレスの項目名に「連絡先メール」を追加して保存。届いたメールを削除して再同期(または新しい通知メールを送る)</li><li>「通知メールの送信元アドレス」にフォームツール役のアドレスを登録し、項目名が全く合わない本文の通知メールを同期</li><li>メールアドレスの形式でない値を送信元アドレスに入れて保存</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>設定なしでは本文を読み取れず、差出人(フォームツール役)が担当者として登録されるか、AI 抽出で問い合わせ者が登録される(どちらになったかメモ)</li><li>項目名を追加した後は本文の問い合わせ者が登録される</li><li>送信元アドレスを登録すると、読み取れなかった場合でもフォームツール役のアドレスは担当者として登録されず、スレッドの担当者は「未登録」になる</li><li>形式違反は「送信元アドレスの形式が正しくありません」で保存できない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-11\"><div><div class=\"cid\">MB-11</div><span class=\"pri p1\">必須</span></div><div class=\"title\">メールテンプレートと差し込み項目、送信前の確認</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>設定 → メールテンプレートで、本文に {{取引先}} {{担当者名}} 様 / {{自社担当者}} / {{問い合わせ本文}} を含む会社共通のテンプレートと、件名に {{案件名}} を含む自分専用のテンプレートを登録。取引先・担当者が付いた受信スレッドと、問い合わせから作った案件がある。</div>\n              <div><div class=\"l\">手順</div><ol><li>スレッドの返信フォームで会社共通のテンプレートを選び、「確認して送信」</li><li>案件詳細 → メール履歴 → 「メールを送る」で自分専用のテンプレートを選ぶ</li><li>受信トレイの「新規作成」で宛先を空のままテンプレートを選び、「確認して送信」</li><li>宛先に登録済みの担当者のアドレスを入れてから、テンプレートを選び直して送信</li><li>別のログインユーザーで返信フォームのテンプレート一覧を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>返信では取引先名・氏名・自分の名前が入り、相手のメールが「&gt;」付きで {{問い合わせ本文}} の位置に入る(末尾に二重には付かない)。署名は本文の後ろに付く</li><li>確認画面に差出人・宛先・件名・本文・添付が出て、「差し込み項目はすべて反映されています」と表示され、送信できる</li><li>案件からは件名に案件名が入り、{{問い合わせ本文}} には元の問い合わせメールが入る</li><li>宛先が空だと {{取引先}} {{担当者名}} が残って黄色の注意が出る。確認画面では赤く示され、送信ボタンが押せない</li><li>宛先を入れて選び直すと登録済みの会社名・氏名が入る</li><li>自分専用のテンプレートは登録した本人以外の一覧に出ない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-12\"><div><div class=\"cid\">MB-12</div><span class=\"pri p1\">必須</span></div><div class=\"title\">テンプレートを使わない差し込みと、画面が低いときの送信ボタン</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>取引先・担当者が付いた受信スレッドと、担当者付きの案件がある。ブラウザの高さを 600px 程度に縮めておく。</div>\n              <div><div class=\"l\">手順</div><ol><li>案件詳細 → メール履歴 → 「メールを送る」を開き、宛先の下の表示を確認</li><li>本文の右上「差し込む」→「宛名」を選び、続けて本文を打つ</li><li>文の途中で「差し込む」→「担当者名」を選ぶ</li><li>「差し込む」→「元の件名」など「この画面では不明」の項目を選び、「確認して送信」</li><li>テンプレートで引用付きの長い本文にし、ダイアログの送信ボタンが見えるか確認</li><li>スレッドの返信フォームでも「差し込む」→「メールを引用」を選んで確認画面まで進む</li><li>受信トレイの「新規作成」で未登録のアドレスを宛先に入れ、宛先欄から離れる</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>宛先の下に「相手: 氏名 / 会社名 / 案件: 案件名」が出る</li><li>本文の先頭に「会社名 / 氏名 様 / 空行」が入り、そのまま続けて打てる(カーソルが本文に残る)</li><li>担当者名がカーソルの位置に入る</li><li>不明な項目は {{元の件名}} のまま入り、確認画面で赤く示されて送信ボタンが押せない</li><li>本文が長くてもダイアログは画面に収まり、フォーム部分だけがスクロールして「確認して送信」が常に見える。確認画面も同様</li><li>返信フォームでは相手のメールが「&gt;」付きで入り、確認画面の本文で末尾に二重には付かない</li><li>未登録のアドレスでは「この宛先は担当者として登録されていません」と出て、「差し込む」の担当者名・取引先が「この画面では不明」になる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-13\"><div><div class=\"cid\">MB-13</div><span class=\"pri p1\">必須</span></div><div class=\"title\">メールのゴミ箱(元に戻す・完全に削除)と一覧の「さらに表示」</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>添付付きのメールを含む受信スレッドが 2 つ以上ある(片方は問い合わせに登録済み、タグ付き)。</div>\n              <div><div class=\"l\">手順</div><ol><li>メール一覧でタグ付きのスレッドにチェックを付けて「削除」→ 確認文を読んで「ゴミ箱に移動」</li><li>通知の「元に戻す」を押す</li><li>もう一度同じスレッドを削除し、今度は通知をそのままにする</li><li>未読数のバッジ・取引先詳細のメール欄・検索で、そのスレッドが出ないことを確認</li><li>一覧右上の「ゴミ箱」を開き、削除した人・日時・「あと 14 日」を確認して「元に戻す」</li><li>メール一覧に戻り、タグ・添付・問い合わせの紐付けが残っていることを確認</li><li>別のスレッドをスレッド画面の「削除」からゴミ箱に入れ、ゴミ箱で「完全に削除」→ 確認</li><li>2 つ以上ゴミ箱に入れ、チェックを付けて上部の「元に戻す」「完全に削除」、最後に「ゴミ箱を空にする」を試す</li><li>(メールが 300 通を超えるテナントで)一覧の下の「さらに表示」を押す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>確認文に「14 日間は元に戻せます」とあり、通知は「n件のメールをゴミ箱に移動しました」+「元に戻す」ボタン</li><li>「元に戻す」で一覧に戻り、未読・タグ・紐付けは元のまま</li><li>ゴミ箱に入っている間は一覧・検索・未読バッジ・取引先や案件のメール欄のどこにも出ない。登録済みの問い合わせ・案件は残る</li><li>ゴミ箱の行に「○○さんが 9/22 10:00 に削除」と「あと 14 日」、「元に戻す」「完全に削除」が並ぶ。「ゴミ箱(1)」のように件数が付く</li><li>「完全に削除」は確認ダイアログの後にゴミ箱から消え、Storage の添付も消えている(運営側で確認)</li><li>チェック選択の操作は選んだスレッドだけに効き、「ゴミ箱を空にする」は確認(スレッド数・通数入り)の後にゴミ箱が空になる</li><li>「さらに表示」を押すと 600 通分までのスレッドが並び、URL に n=2 が付く。上限に届かなければボタンは出ない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-14\"><div><div class=\"cid\">MB-14</div><span class=\"pri\">通常</span></div><div class=\"title\">タグ付けルールの「宛先」</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>info@ など、特定のアドレス宛てに届いた受信メールがある。</div>\n              <div><div class=\"l\">手順</div><ol><li>設定 → タグ → 自動で付けるルールで「宛先」を選び、そのアドレスと付けるタグを登録</li><li>行の「過去分にも適用」を押す</li><li>そのアドレス宛てに新しいメールを送って同期する</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「宛先」を選ぶと入力欄の例が「メールアドレス(「、」区切りでいずれか)」に変わる</li><li>過去分にも適用で、そのアドレスが To または CC に入ったメール(スレッド)にタグが付き、件数が表示される</li><li>同期で取り込んだ新しいメールにも自動で付く。差出人や件名の条件には影響しない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-15\"><div><div class=\"cid\">MB-15</div><span class=\"pri\">通常</span></div><div class=\"title\">メールアカウントでの絞り込み</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>メールアカウントを 2 つ以上連携し、それぞれで受信したメールがある。</div>\n              <div><div class=\"l\">手順</div><ol><li>メール一覧を開き、タグの行の上に「アカウント:」の行が出ることを確認</li><li>片方のアカウントを押す</li><li>その状態でタグ・検索・「未読」などを組み合わせる</li><li>全選択してタグを付ける</li><li>「解除」を押す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>アカウントが 1 つだけのテナントでは行が出ない</li><li>押したアカウントで受信・送信したスレッドだけが並び、他の条件と併用できる。URL に account= が付く</li><li>絞り込んでいないときは各行の右にアカウント名(表示名)が出る。絞り込み中は出ない</li><li>タグ付けはそのアカウントのメールだけに付く</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-16\"><div><div class=\"cid\">MB-16</div><span class=\"pri\">通常</span></div><div class=\"title\">メールアカウントごとの署名</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>メールアカウントが 2 つあり、設定画面の共通の署名(会社名・追加行)が入っている。</div>\n              <div><div class=\"l\">手順</div><ol><li>片方のアカウントの編集画面を開き、「このアカウント専用の署名」に {{自社担当者}} と {{自社メール}} を含む文面を入れて保存</li><li>受信トレイの「新規作成」を開き、本文末尾の署名を確認</li><li>送信元をもう片方のアカウントに切り替える</li><li>本文の署名を手で消してから送信元を切り替える</li><li>スレッドの返信フォームでも同じ確認をする</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>専用の署名を入れたアカウントでは、区切り線 + その文面(担当者名・アドレスが置き換わったもの)が署名になる</li><li>もう片方(専用の署名なし)では共通の署名で、「メールアドレス:」の行がそのアカウントのアドレスになる</li><li>送信元を切り替えると本文の署名だけが入れ替わり、書きかけの本文は残る</li><li>署名を消してあれば、切り替えても何も足されない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MB-08\"><div><div class=\"cid\">MB-08</div><span class=\"pri\">通常</span></div><div class=\"title\">スレッドと案件の紐付け</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>案件が 1 件以上ある。</div>\n              <div><div class=\"l\">手順</div><ol><li>スレッド画面の「案件を選択」で案件に紐付ける</li><li>案件詳細でメールが表示されることを確認し、紐付けを外す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>案件詳細の関連メールにスレッドが出る</li><li>外すと消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 5 ===================== -->\n      <section id=\"inquiry\">\n        <h2><span class=\"id\">§5</span>問い合わせ</h2>\n        <p class=\"intro\">メール一覧で選んだメールを問い合わせとして登録し、状態(新規 → 対応中 → 案件化 / 完了)を管理します。同期で自動登録はされません。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"IQ-01\"><div><div class=\"cid\">IQ-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">メールから問い合わせを登録</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>メール一覧で受信メールを 2 通選択し「問い合わせに登録」</li><li>同じメールでもう一度登録</li><li>問い合わせ一覧を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>2 件が「新規」で登録され、件名・取引先・担当者・メール本文が表示される</li><li>登録済みのメールは重複登録されず、その旨が表示される</li><li>サイドメニューの「問い合わせ」に新規件数のバッジが出る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IQ-02\"><div><div class=\"cid\">IQ-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">状態変更と案件化(アポ取得)</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>問い合わせを「対応中」にする</li><li>「アポ取得」で案件化し、案件名などを入力</li><li>案件カンバンを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>状態が順に変わり、案件化すると「案件化」になって案件へのリンクが付く</li><li>案件はステージ「アポ取得」に作られ、取引先・担当者が引き継がれる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IQ-04\"><div><div class=\"cid\">IQ-04</div><span class=\"pri p1\">必須</span></div><div class=\"title\">担当者・メモ・タグ</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「新規」の問い合わせで「担当者」に営業担当を選ぶ</li><li>担当者を「担当者なし」に戻す</li><li>「メモを追加」で経過を書いて保存 → 鉛筆で編集 → 空にして保存</li><li>「タグを付ける」でタグを付け、メール画面で同じスレッドを開く</li><li>上部の「担当者:」とタグで絞り込む</li><li>担当者とメモを付けた問い合わせを「案件化」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>担当者を付けるとステータスが「対応中」に変わり、その旨のトーストが出る。外してもステータスは戻らない</li><li>メモは保存後に日時と更新者付きで表示され、空にすると「メモを追加」に戻る</li><li>スレッド画面の関連情報にも同じタグが付いている(メール側で外すと問い合わせ側からも消える)</li><li>「未割当」は担当者なしだけ、営業担当名はその人の分だけ、タグはそのタグのメールが属する問い合わせだけになる</li><li>案件作成ダイアログの営業担当とメモに問い合わせの値が入っている</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IQ-03\"><div><div class=\"cid\">IQ-03</div><span class=\"pri\">通常</span></div><div class=\"title\">手動登録と削除</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「追加」で件名なしで登録 → 件名ありで登録</li><li>削除ボタン → 確認ダイアログでキャンセル → 再度削除で確定</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>件名なしは「件名は必須です」</li><li>キャンセルでは消えず、確定で消える。紐付いていたメールは残る</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 6 ===================== -->\n      <section id=\"deals\">\n        <h2><span class=\"id\">§6</span>案件と売上</h2>\n        <p class=\"intro\">ステージは アポ取得 → 提案書作成中 → 提案済み → 検討中 → 保留 → 成約 / 失注。成約には月次売上の入力が必須です。案件の「行動」タブで電話・メール・訪問などの履歴と期限付き Todo を管理し、期限超過は赤で警告します。行動の種類は設定画面で追加・並び替えでき、期限・アポイント日時・受注予定日は「今日・明日…」のボタンと 2 週間タイルのカレンダーで入力します(過去の日は選べません)。</p>\n        <div class=\"scroll\"><table class=\"rules\">\n          <thead><tr><th>ステージ</th><th>確度</th><th>備考</th></tr></thead>\n          <tbody>\n            <tr><td>アポ取得</td><td class=\"num\">30%</td><td>問い合わせからの案件化時の初期ステージ</td></tr>\n            <tr><td>提案書作成中</td><td class=\"num\">40%</td><td></td></tr>\n            <tr><td>提案済み</td><td class=\"num\">50%</td><td></td></tr>\n            <tr><td>検討中</td><td class=\"num\">60%</td><td></td></tr>\n            <tr><td>保留</td><td class=\"num\">20%</td><td></td></tr>\n            <tr><td>成約</td><td class=\"num\">100%</td><td>売上明細(金額と計上月)が 1 件以上必須。金額の合計が案件金額になる</td></tr>\n            <tr><td>失注</td><td class=\"num\">0%</td><td>失注理由を入力</td></tr>\n          </tbody>\n        </table></div>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"DL-01\"><div><div class=\"cid\">DL-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">案件の作成・編集・カンバン移動</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「追加」で取引先なし・案件名なしで保存</li><li>取引先と案件名、金額、営業担当を入れて保存</li><li>カードをドラッグして「提案済み」へ、同じ列内で並べ替え</li><li>詳細でメモを追加・削除</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>取引先と案件名が必須のエラーが出る</li><li>移動後に再読み込みしてもステージと並び順が保たれる</li><li>ダッシュボードの「ステージ別パイプライン」に反映される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-02\"><div><div class=\"cid\">DL-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">成約には売上入力が必須</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>案件を「成約」へ移動し、売上入力を空のまま確定</li><li>計上月 2 か月分(例: 今月 100,000 / 来月 50,000)を入れて確定</li><li>売上ページとダッシュボードを確認</li><li>成約の案件を「検討中」に戻す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>空のままは「売上明細を 1 件以上入力してください」で止まる</li><li>確定後、案件金額が 150,000 になり成約日が付く</li><li>売上ページの該当月に金額が計上され、年間合計が合う</li><li>戻すと成約日が消え、売上明細も消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-03\"><div><div class=\"cid\">DL-03</div><span class=\"pri\">通常</span></div><div class=\"title\">失注と失注理由</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>案件を「失注」へ移動し理由を入力</li><li>失注の案件を「提案済み」に戻す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>詳細に失注理由が表示される</li><li>戻すと理由が消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-05\"><div><div class=\"cid\">DL-05</div><span class=\"pri p1\">必須</span></div><div class=\"title\">行動の登録・完了・期限超過の警告</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>進行中の案件が 1 件ある。</div>\n              <div><div class=\"l\">手順</div><ol><li>案件詳細の「行動」タブで、種類「電話」・内容を入れ、期限を「今日」+「時刻を指定…」で現在より前の時刻(例: 08:00)にして登録(過去の日付は選べないため、当日の過ぎた時刻で期限超過を作る)</li><li>種類「見積書作成」で期限「今日」+「時刻なし(終日)」、種類「電話折り返し依頼」で期限「日付を選ぶ」のタイルから 5 日後を選んで登録</li><li>種類「訪問」で「済んだ行動として記録する」にチェックして登録</li><li>案件一覧(カンバン)とダッシュボードを確認</li><li>期限を過ぎた行動にチェックを付けて完了にし、再度確認</li><li>鉛筆で内容と期限を編集、ゴミ箱で 1 件削除</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>期限を過ぎた行動は赤い背景と「期限超過」バッジ、タブに「超過 1」の赤いバッジ、上部に「期限を過ぎた行動が 1 件あります」の警告</li><li>終日の行動は黄色の「今日」で、期限は日付だけ(時刻なし)で表示される。5 日後は「予定」扱い(バッジなし)、済んだ行動は打ち消し線と完了日時で下に並ぶ</li><li>並び順は 期限超過 → 今日 → 5 日後 → 完了 の順</li><li>カンバンのカードに「期限超過 1」「今日 1」、サイドバーの「行動」に赤いバッジ「1」、ダッシュボードの「進行中の案件」に「期限超過の行動 1 件」、「今日やること」に 3 件(期限超過・今日・5 日後)が種類・内容・案件名・取引先付きで並ぶ</li>\n                <li>サイドバーの「行動」ページで、期限超過 / 今日 / それ以降 のグループに分かれて表示され、期限超過の行のチェックを付けると完了になり一覧から消える。「完了済みも表示」で完了分が見える</li><li>完了にすると警告とバッジが消え、カンバン・ダッシュボードからも減る</li><li>編集・削除が反映される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-06\"><div><div class=\"cid\">DL-06</div><span class=\"pri p1\">必須</span></div><div class=\"title\">行動の種類の設定(追加・編集・並び替え・削除の制限)</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>DL-05 で種類「電話」を使った行動がある。</div>\n              <div><div class=\"l\">手順</div><ol><li>設定 → 「行動の種類」で既定の 6 個(電話・メール・訪問・見積書作成・電話折り返し依頼・その他)を確認</li><li>「オンライン商談」をアイコン「Web 会議」で追加</li><li>上下の矢印で「オンライン商談」を先頭に移動し、ページを再読み込み</li><li>「見積書作成」の名前を「見積提出」に、アイコンを「契約・書類」に変更</li><li>「電話」を削除 → 「オンライン商談」を削除</li><li>同じ名前「メール」で追加、21 個目を追加</li><li>案件詳細の「行動」タブを開き、種類ボタンの並びを確認。新規テナント(会社 B)の設定も確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>既定 6 個が最初から入っている(会社 B にも同じ 6 個)</li><li>追加した種類がアイコン付きで一覧に出て、並び替えは再読み込み後も保たれる</li><li>名前・アイコンの変更は、登録済みの行動の表示(行動タブ・行動一覧・ダッシュボード)にも反映される</li><li>使用中の「電話」は「この種類を使っている行動が 1 件あるため削除できません」で止まり、未使用の「オンライン商談」は削除できる。残り 1 個になったときは「最低 1 個必要」で削除できない</li><li>同名は「同じ名前の種類があります」、21 個目は上限エラー</li><li>行動タブの種類ボタンが設定の並び順どおりで、先頭の種類が最初から選ばれている</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-07\"><div><div class=\"cid\">DL-07</div><span class=\"pri p1\">必須</span></div><div class=\"title\">期限・アポイント日時・受注予定日の入力部品</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>進行中の案件が 1 件ある。PC とスマホ(または幅 400px 程度)の両方で確認。</div>\n              <div><div class=\"l\">手順</div><ol><li>行動タブで「明日」を押し、続けて「午後 14:00」を押して登録</li><li>「日付を選ぶ」を押してタイルを開き、‹ › と「今日に戻る」で週を動かし、次の週の平日を選んで「時刻を指定…」で 09:30 を選び登録</li><li>「日付を選ぶ」で祝日(9 月なら 21〜23 日)と土日の表示、今日より前のタイルを押せるかを確認</li><li>日付を選んだあと「時刻なし(終日)」のまま登録し、「クリア」で未設定に戻して期限なしでも登録</li><li>登録済みの行動を鉛筆で開き、期限の初期表示が保存した日時と一致することを確認して別の日に変更</li><li>案件の編集(鉛筆)でアポイント日時を「来週◯曜」+「13:00」、受注予定日を「来月末」にして保存。案件の新規作成でも同じ部品が出ることを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>日付ボタンは 今日・明日・明後日・来週◯曜・1 週間後・日付を選ぶ の 6 個。押すと時刻ボタン(午前中 10:00・午後 14:00・夕方 17:00・時刻なし(終日)・時刻を指定…)が現れ、下に「9月16日(水) 14:00 · 明後日」のように確定内容が出る</li><li>タイルは 7 列 × 2 段の 14 日分。曜日と日付が大きく、月が変わる日に「◯月」、祝日は赤い「祝」と祝日名。土日祝は薄い背景で選べる。今日より前は薄く押せない。‹ は今日を含む週で無効</li><li>選んだ日がボタンに無い日のときは「日付を選ぶ」ボタンがその日付の表示に変わる</li><li>「時刻なし(終日)」で登録した行動は一覧で日付だけが表示され、その日のうちは「今日」、翌日になると「期限超過」になる</li><li>編集ダイアログの初期表示が保存内容と一致する(日付ボタンに該当する日はそのボタンが選択状態、時刻は該当ボタンまたはプルダウン)</li><li>アポイント日時には「時刻なし」が無く、時刻ボタンは 10:00・13:00・14:00・16:00。受注予定日は「今月末・来月末・再来月末・日付を選ぶ」で時刻なし。保存後の詳細画面・カンバンのカードに反映される</li><li>スマホ幅でもタイルが横にはみ出さず、ボタンが折り返して押せる</li></ul></div></div>\n          <div class=\"case\" data-id=\"DL-08\"><div><div class=\"cid\">DL-08</div><span class=\"pri p1\">必須</span></div><div class=\"title\">行動(Todo)の担当者と担当者での絞り込み</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>営業担当者が 2 人以上いて(A=自分、B=別の担当者)、案件の担当者が A の案件と、担当者未設定の案件がある。</div>\n              <div><div class=\"l\">手順</div><ol><li>担当者 A の案件の「行動」タブを開き、登録フォームの「担当者」の初期値を確認して、そのまま「電話」を期限「明日」で登録</li><li>もう 1 件、担当者を B に変えて「見積書作成」を期限「今日」で登録</li><li>担当者未設定の案件の「行動」タブで初期値を確認し、担当者を「担当者なし」にして 1 件登録</li><li>サイドバーの「行動」を開き、「担当者:」の B を押す → A を押す → 「担当者なし」を押す → 「解除」</li><li>B で絞り込んだ状態で「完了済みも表示」を押し、URL と一覧を確認</li><li>行動一覧の行で「担当者なし」の文字を押して A に変える。ダッシュボードの「今日やること」でも担当者名を押して B に変える</li><li>鉛筆の編集で担当者を変えて保存</li><li>案件の編集でアポイント日時を入れて保存し、自動で作られた「アポイント」Todo の担当者を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>初期値は案件の担当者(A)。担当者未設定の案件では自分(A)が初期値になる</li><li>行動タブの各行に担当者名がアイコン付きで出る。「担当者なし」の行には出ない</li><li>行動一覧は B を押すと B の行動だけ(「見積書作成」)、A を押すと A の行動だけになり、押した名前が選択状態(自分には「(自分)」)。「担当者なし」で未割り当てだけ、「解除」で全員分に戻る。該当が無いときは「「B」の未完了の行動はありません」と絞り込み解除のリンクが出る</li><li>「完了済みも表示」を押しても担当者の絞り込みは保たれ(URL に done=1 と owner=…)、完了済みの見出しに担当者名が付く</li><li>行やダッシュボードで担当者を変えると「担当者を変更しました」と出て、再読み込み後も反映され、絞り込みの結果も変わる</li><li>編集ダイアログの担当者の初期値は保存済みの担当者で、変更が反映される</li><li>「アポイント」Todo の担当者は案件の担当者になる</li><li>営業担当者を「利用停止」にしても、その人が付いている行動の名前は表示され続ける(選択肢には出ない)</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"DL-04\"><div><div class=\"cid\">DL-04</div><span class=\"pri\">通常</span></div><div class=\"title\">売上ページの年切り替えと削除の影響</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>売上ページで年を切り替える</li><li>成約案件を削除して売上ページを再確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>年ごとの月次表と年間合計が切り替わる</li><li>案件を削除すると売上も消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 7 ===================== -->\n      <section id=\"master\">\n        <h2><span class=\"id\">§7</span>取引先・担当者・タグ</h2>\n        <p class=\"intro\">取引先(companies)と担当者(contacts)はメールから自動登録され、手動でも編集できます。重複して作られたものは統合でまとめます。タグは担当者の属性管理と CSV 出力に使います。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"MS-01\"><div><div class=\"cid\">MS-01</div><span class=\"pri\">通常</span></div><div class=\"title\">取引先の追加・編集・削除</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>取引先を追加し、詳細で担当者を追加</li><li>取引先名を編集</li><li>案件が紐付いている取引先を削除</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>詳細に担当者・案件・メールの一覧が出る</li><li>削除時は紐付くデータへの影響が案内され、削除後に案件側の取引先が外れる(または削除が止まる)。挙動をメモに記録</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-02\"><div><div class=\"cid\">MS-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">担当者のタグ絞り込みと CSV 出力</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>MB-07 で「リード」を付けた担当者がいる。</div>\n              <div><div class=\"l\">手順</div><ol><li>担当者一覧でタグ「リード」で絞り込む</li><li>担当者を選択してタグ「顧客」を追加、「リード」を外す</li><li>「CSV ダウンロード」を実行し Excel で開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>絞り込みで該当者だけになる</li><li>タグの付け外しが即時反映される</li><li>CSV は絞り込み条件を反映し、文字化けせず(BOM 付き UTF-8)、氏名・会社・メール・タグ列がある</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-04\"><div><div class=\"cid\">MS-04</div><span class=\"pri p1\">必須</span></div><div class=\"title\">取引先の統合</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>取引先 X(ドメインあり、案件 1 件・売上あり・担当者 1 名・メールあり)と、同じ会社を指す取引先 Y(ドメインなし、担当者 1 名・問い合わせ 1 件)。</div>\n              <div><div class=\"l\">手順</div><ol><li>取引先 Y の詳細で「統合」を押し、X を検索して「「X」に統合する」(一覧からの統合は MS-07)</li><li>X の詳細と、担当者一覧・問い合わせ・案件・売上ページを確認</li><li>X の詳細で「統合」を開き、X 自身が候補に出ないことを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>確認文に統合元・統合先の名前と「元に戻せません」が出て、統合後は X の詳細に遷移する</li><li>Y の担当者・メール・問い合わせが X に移り、Y は一覧から消える</li><li>X の案件・売上はそのまま。X のドメインなど埋まっている項目は上書きされず、空欄だけ Y の値で埋まる(メモは連結)</li><li>Y のドメインが X に無かった場合は引き継がれる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-05\"><div><div class=\"cid\">MS-05</div><span class=\"pri p1\">必須</span></div><div class=\"title\">担当者の統合</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>同じ人を指す担当者 P(メールあり、タグ「リード」、メール 2 通、問い合わせ 1 件)と Q(メールなし、電話あり、タグ「顧客」、案件 1 件の担当)。</div>\n              <div><div class=\"l\">手順</div><ol><li>担当者一覧で Q の行の統合アイコン(矢印が合流する形)を押し、P を検索して統合</li><li>P の詳細(取引先詳細の担当者タブ)、メール一覧、問い合わせ、案件を確認</li><li>取引先詳細の担当者タブからも同じ操作ができることを確認(別の重複ペアで)</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>Q のメール・問い合わせ・案件の担当者が P になり、Q は消える</li><li>P のタグが「リード」「顧客」の両方になる(重複しない)</li><li>P の電話が空なら Q の電話で埋まる。P のメールアドレスは変わらない</li><li>確認文に、統合元のメールアドレスが残らない旨の注意が出る(統合元にメールがある場合)</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-07\"><div><div class=\"cid\">MS-07</div><span class=\"pri p1\">必須</span></div><div class=\"title\">取引先一覧からの複数統合</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>同じ会社を指す取引先が 3 件(A: 担当者 2 名・案件 1 件、B: 担当者 1 名・ドメインあり、C: 担当者 0 名・問い合わせ 1 件)。</div>\n              <div><div class=\"l\">手順</div><ol><li>取引先一覧で A だけにチェックを付け、上部の「統合」ボタンが押せない(2 社以上の案内)ことを確認</li><li>A・B・C にチェックを付けて「統合」を押す</li><li>ダイアログで最初に選ばれている会社を確認し、そのまま「「A」に 2 社を統合する」を押す</li><li>一覧・A の詳細・担当者一覧・問い合わせを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>1 社だけでは統合ボタンが無効。2 社以上で有効になる</li><li>ダイアログには選んだ 3 社が並び、担当者・案件の多い A が「残す」として最初から選ばれている。別の会社を押すとそちらが「残す」に切り替わる</li><li>統合後、B・C は一覧から消え、B の担当者と C の問い合わせが A に移る。A のドメインが空なら B のドメインが引き継がれる</li><li>チェックが解除され、一覧が更新される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-08\"><div><div class=\"cid\">MS-08</div><span class=\"pri p1\">必須</span></div><div class=\"title\">フリーメールの相手の取引先判定(会社名・表記ゆれ・格上げ)</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>Gmail のアドレス 2 つ(G1・G2)と、プロバイダーのアドレス 1 つ(P1、例: xxx@ocn.ne.jp)から自社の受信アカウントへメールを送れること。</div>\n              <div><div class=\"l\">手順</div><ol><li>G1 から署名に「株式会社テスト商事」と書いたメールを送り、同期</li><li>G2 から署名に「テスト商事(株)」と書いたメールを送り、同期</li><li>P1 から署名なしのメールを送り、同期</li><li>P1 から署名に「株式会社テスト商事」と書いた別件のメール(返信ではない新規)を送り、同期</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>手順 1 で取引先「株式会社テスト商事」(ドメインなし)と G1 の担当者ができる</li><li>手順 2 で G2 の担当者は同じ「株式会社テスト商事」に入り、「テスト商事(株)」という取引先は作られない</li><li>手順 3 で P1 は「氏名(個人)」の取引先になる。「Ocn」のようなプロバイダー名の取引先は作られない</li><li>手順 4 で P1 の担当者が「株式会社テスト商事」に移り、それまでのメールも同じ取引先に付く。「氏名(個人)」は空になって一覧から消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-06\"><div><div class=\"cid\">MS-06</div><span class=\"pri\">通常</span></div><div class=\"title\">担当者の所属変更がメール・問い合わせに波及する</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>担当者 R(取引先 X 所属、メール 2 通・問い合わせ 1 件・案件 1 件)。</div>\n              <div><div class=\"l\">手順</div><ol><li>R を編集して会社を取引先 Z に変更</li><li>取引先 X と Z の詳細の「メール」「問い合わせ」「案件」タブを確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>R のメールと問い合わせの取引先が Z に変わる(X のタブから消え、Z のタブに出る)</li><li>案件は X に残ったまま(案件は取引先に属するため動かさない)</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"MS-03\"><div><div class=\"cid\">MS-03</div><span class=\"pri\">通常</span></div><div class=\"title\">タグ設定(既定 6 個、最大 20 個、並び替え)</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>設定 → タグで既定の 6 個(リード・セールス・パートナー・顧客・失注・要注意)を確認</li><li>名前と色を変更、新しいタグを追加</li><li>上下の矢印で「要注意」を先頭に移動し、ページを再読み込み</li><li>メール一覧のタグ絞り込み・選択時のタグメニュー、担当者一覧のタグ絞り込みを開く</li><li>合計 21 個目を追加</li><li>使用中のタグを削除</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>新規テナントにも既定 6 個が最初から入っている</li><li>並び替えは再読み込み後も保たれ、タグの選択肢と絞り込みの並びが設定の順になる</li><li>21 個目は上限エラー</li><li>削除するとメール・担当者からもそのタグが消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 8 ===================== -->\n      <section id=\"members\">\n        <h2><span class=\"id\">§8</span>営業担当者</h2>\n        <p class=\"intro\">自社の営業担当者(members)。案件の担当と署名の名前に使われ、招待するとログインできます。招待・削除の詳細は §2 を参照。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"MM-01\"><div><div class=\"cid\">MM-01</div><span class=\"pri\">通常</span></div><div class=\"title\">担当者の追加・並び順・無効化と案件担当</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>メールアドレスなしで担当者を追加</li><li>その担当者を案件の担当に設定</li><li>担当者を無効にして案件の担当者選択を確認</li><li>担当者を削除して案件詳細を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>メールなしでも登録でき、「招待」は押せない(メール登録を促す)</li><li>無効な担当者は選択肢から外れる(既存の設定は残る)</li><li>削除すると案件の担当が「未設定」になる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 9 ===================== -->\n      <section id=\"settings\">\n        <h2><span class=\"id\">§9</span>設定とログ</h2>\n        <p class=\"intro\">署名・返信件名、通知先、システムログ、ヘルスチェック。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"ST-01\"><div><div class=\"cid\">ST-01</div><span class=\"pri\">通常</span></div><div class=\"title\">署名と返信件名の保存</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>会社名・メール・追記・返信件名を変更して保存</li><li>返信フォームを開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>保存トーストが出て、再読み込み後も残る</li><li>返信フォームの署名と件名に反映される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ST-05\"><div><div class=\"cid\">ST-05</div><span class=\"pri\">通常</span></div><div class=\"title\">メールテンプレートの登録と上限</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>設定 → メールテンプレートで「追加」。差し込み項目のボタンを押して本文に入れ、会社共通で保存</li><li>同じテンプレートを編集して「自分専用」に変えて保存</li><li>名前を空、本文を空で保存</li><li>会社共通を 10 個にしてから 11 個目を追加</li><li>1 つ削除</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>ボタンでカーソル位置に {{取引先}} などが入り、保存すると一覧に「会社共通」のバッジで並ぶ</li><li>自分専用に変えるとバッジが変わり、返信フォームの一覧では「自分専用」のグループに出る</li><li>名前・本文が空だと「入力してください」で保存できない</li><li>11 個目は「会社共通のテンプレートは 10 個までです」で止まる</li><li>削除すると一覧と返信フォームの選択肢から消える</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ST-02\"><div><div class=\"cid\">ST-02</div><span class=\"pri\">通常</span></div><div class=\"title\">複数メールアカウントと既定の差出人</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>メールアカウント上限 2 以上。</div>\n              <div><div class=\"l\">手順</div><ol><li>2 件目を追加し、既定を切り替える</li><li>新規作成で差出人を選んで送信</li><li>1 件目を無効にして同期</li><li>上限を超えて 3 件目を追加</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>新規作成の既定の差出人が切り替わる</li><li>無効なアカウントは同期・送信の対象外</li><li>3 件目は「連携メールアカウント数の上限」で止まる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ST-03\"><div><div class=\"cid\">ST-03</div><span class=\"pri\">通常</span></div><div class=\"title\">通知先メールとテスト通知、システムログ</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>通知先メールを 2 件(カンマ区切り)にして保存、「テスト通知を送る」</li><li>誤ったアプリパスワードで同期してエラーを起こす</li><li>設定 → システムログを開き、30 日より古いログの削除を実行</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>テスト通知が両方に届く</li><li>同期エラーがログに error で残り、通知メールが届く。同じ発生箇所は 30 分に 1 回しか通知されない</li><li>ログ一覧でレベル・発生箇所・日時が見え、削除件数が表示される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"ST-04\"><div><div class=\"cid\">ST-04</div><span class=\"pri\">任意</span></div><div class=\"title\">ヘルスチェック</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>未ログインのブラウザで <code>https://sfa.art-trading.net/api/health</code> を開く</li><li>ログイン中のブラウザで開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>未ログインは DB の確認だけで ok: true</li><li>ログイン中は自社の IMAP / SMTP 接続も確認され、失敗があると 503</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 10 ===================== -->\n      <section id=\"admin\">\n        <h2><span class=\"id\">§10</span>運営管理</h2>\n        <p class=\"intro\">運営者だけが開ける <code>/admin</code>。テナントの一覧・作成・詳細、料金、運営者の招待、メールテンプレート。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"AD-01\"><div><div class=\"cid\">AD-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">テナント一覧と月額合計</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>運営者でログインし /admin を開く</li><li>各テナントのユーザー・メールアカウント・容量・月額・お試し期限を確認</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>利用数が実際と一致し、上限到達は赤字</li><li>月額合計は「課金中」かつ自社以外のテナントの合計</li><li>経路(Web 申し込み / 運営が作成)が見分けられる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-02\"><div><div class=\"cid\">AD-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">運営からのテナント作成と招待</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>テナントを作成(上限・お試し日数を指定)</li><li>招待メールが届くこと、または失敗時にリンクが表示されることを確認</li><li>詳細から招待を再送</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>招待メールは運営側の Gmail から送られ、リンクからパスワード設定できる</li><li>指定した上限・お試し期限が詳細に反映される</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-03\"><div><div class=\"cid\">AD-03</div><span class=\"pri\">通常</span></div><div class=\"title\">テナント詳細の編集(契約状態・上限・連絡先)と Stripe 情報</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>契約状態を「停止中」にしてテナント側を確認、戻す</li><li>上限を変更してテナント側の「N / 上限」を確認</li><li>連絡先・運営メモを編集</li><li>Stripe カードの顧客・サブスクリプションのリンクと「今すぐ同期」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>停止中はテナント側が閲覧のみになり、cron 同期の対象外</li><li>運営メモはテナント側に表示されない</li><li>Stripe のリンクがテストモードのダッシュボードを開く。同期後に数量が合う</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-04\"><div><div class=\"cid\">AD-04</div><span class=\"pri\">通常</span></div><div class=\"title\">テナント削除</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>契約中(Stripe サブスクリプションあり)のテスト用テナント。</div>\n              <div><div class=\"l\">手順</div><ol><li>削除で会社 ID を間違えて入力 → 正しく入力</li><li>自社テナントの削除を試す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>会社 ID が違うと削除されない</li><li>削除すると業務データ・添付・利用者の所属が消え、Stripe のサブスクリプションがキャンセルされる</li><li>自社テナントは「削除できません」</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-05\"><div><div class=\"cid\">AD-05</div><span class=\"pri\">通常</span></div><div class=\"title\">運営者の招待と削除(スーパーユーザーのみ)</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>/admin/users から未登録のメールアドレスで新しい運営者を招待し、リンクからパスワード設定</li><li>その運営者でテナント側の画面(/ や /inbox)を開く</li><li>運営側の会社(art-trading)の利用者のメールで招待し、届いたリンクを開く。その人でテナント側の画面と /admin の両方を開く</li><li>他社(会社 A など)の利用者のメールで招待</li><li>手順 1 の運営者と手順 3 の運営者をそれぞれ削除し、手順 3 の人でテナント側にログインし直す</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>未登録メールで招待された運営者は /admin に入れ、テナント側の画面は開けず /admin に戻される</li><li>自社の利用者はエラーにならず招待でき、リンクを開くとログイン状態で /admin が開く。テナント側の画面も使え、サイドバーの下に「運営管理」が出る</li><li>他社の利用者は「他社(テナント)の利用者として登録されています」のエラーで招待できない。エラーは 15 秒表示され、× で閉じられる</li><li>運営専用の運営者は削除すると auth ユーザーごと消えてログインできない。自社の利用者は運営者から外れるだけで、テナント側には引き続きログインできる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-06\"><div><div class=\"cid\">AD-06</div><span class=\"pri\">通常</span></div><div class=\"title\">メールテンプレートの編集</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>「Web 申し込みの確認メール」の本文から {{link}} を消して保存</li><li>文言を変えて保存し、SU-01 を再実行</li><li>「パスワード再設定」の件名を変えて保存し、ON-07 を再実行</li><li>「既定に戻す」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>{{link}} なしは保存を拒否される</li><li>変更した文言でメールが届き、差し込み項目が置き換わる</li><li>パスワード再設定メールも変更した件名で届く(5 種類すべて保存できる)</li><li>既定に戻せる</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"AD-07\"><div><div class=\"cid\">AD-07</div><span class=\"pri\">通常</span></div><div class=\"title\">ステップメール(お試し中の顧客への自動メール)</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>運営側テナントに既定のメールアカウントがある。運営管理 → ステップメールに既定の 6 回が入っている。</div>\n              <div><div class=\"l\">手順</div><ol><li>「0 日目 登録のお礼」を押し、「サンプルでプレビュー」→「自分にテスト送信」</li><li>件名を少し変えて保存し、「回を追加」で 30 日目の回を作って保存 → 削除</li><li>テナントを新規作成(申し込みでも可)し、翌朝の定期処理後にそのテナント詳細の「ステップメール」を確認</li><li>導入前からあるテナントの詳細を開き、「このテナントにステップメールを送る」の状態を確認</li><li>任意のテナントで「送る」をオフにし、翌朝の履歴を確認</li><li>一覧の下の「送信元」で別のアカウント、または差出人アドレス(そのアカウントで送信できるエイリアス)と差出人名を入れて保存し、もう一度「自分にテスト送信」</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>プレビューは山田 太郎 / 株式会社サンプルで差し込まれ、末尾に運営の会社名・問い合わせ先が付く。テスト送信は自分のアドレスに「[テスト]」付きの件名で届く</li><li>送信元を変えた後のテスト送信は、その差出人名・アドレスで届き、返信先も差出人アドレスになる。空に戻すと既定のアカウントの名前・アドレスに戻る</li><li>保存・追加・削除が一覧に反映され、一覧は日数順</li><li>新しいテナントには作成日の翌朝に 0 日目、その翌朝に 1 日目が届き、履歴に「送信済み」と宛先・日時が並ぶ。カード登録済みのテナントでは 7 / 14 / 21 日目が「見送り(課金開始後のため)」になる</li><li>導入前からあるテナントはオフになっていて履歴が増えない</li><li>オフにしたテナントには以後届かず、履歴も増えない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n\n      <!-- ===================== 11 ===================== -->\n      <section id=\"isolation\">\n        <h2><span class=\"id\">§11</span>テナント分離と権限</h2>\n        <p class=\"intro\">同じ URL・同じデータベースを複数の会社が使うため、他社のデータが見えないことが最重要です。</p>\n        <div class=\"cases\">\n          <div class=\"case\" data-id=\"IS-01\"><div><div class=\"cid\">IS-01</div><span class=\"pri p1\">必須</span></div><div class=\"title\">他社のデータが見えない・触れない</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>会社 A と会社 B にそれぞれデータ(取引先・案件・メール)がある。</div>\n              <div><div class=\"l\">手順</div><ol><li>会社 A でログインし、各一覧・ダッシュボード・検索・CSV を確認</li><li>会社 B の案件 URL(/deals/〔ID〕)や添付 URL(/api/attachments/〔ID〕)を直接開く</li><li>会社 B の担当者 ID を指定してタグ付けなどの操作を試みる</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>会社 B のデータは一切表示されず、件数にも含まれない</li><li>直接 URL は「見つかりません」または 404</li><li>操作は対象なしとして何も変わらない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IS-02\"><div><div class=\"cid\">IS-02</div><span class=\"pri p1\">必須</span></div><div class=\"title\">一般利用者は運営管理に入れない</div>\n            <div class=\"body\">\n              <div><div class=\"l\">手順</div><ol><li>会社 A の利用者で /admin を開く</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>運営管理は表示されず、テナント側の画面に戻されるか拒否される</li><li>サイドメニューに運営管理のリンクが出ない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IS-03\"><div><div class=\"cid\">IS-03</div><span class=\"pri\">通常</span></div><div class=\"title\">どの会社にも所属しない利用者</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>運営管理でテナントを削除された利用者、または削除後に残った auth ユーザー。</div>\n              <div><div class=\"l\">手順</div><ol><li>その利用者でログイン</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>「どの会社(テナント)にも所属していません」の案内とログアウトだけが表示され、データは見えない</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n\n          <div class=\"case\" data-id=\"IS-04\"><div><div class=\"cid\">IS-04</div><span class=\"pri\">通常</span></div><div class=\"title\">定期 cron の対象</div>\n            <div class=\"body\"><div class=\"pre\"><span class=\"l\">前提</span>CRON_SECRET を知っている運営者が実施。</div>\n              <div><div class=\"l\">手順</div><ol><li><code>Authorization: Bearer 〔CRON_SECRET〕</code> を付けて /api/mail/sync、/api/mail/maintenance、/api/health を呼ぶ</li></ol></div>\n              <div><div class=\"l\">期待結果</div><ul><li>お試し期限内・契約中のテナントだけが同期され、停止中・解約・期限切れは対象外(応答の tenants 一覧で確認)</li><li>シークレットなしは 401</li></ul></div></div>\n            <div class=\"res\"></div><div class=\"memo\"><input placeholder=\"メモ\"></div></div>\n        </div>\n      </section>\n    </main>\n  </div>\n</div>\n\n<script>\n(function () {\n  var KEY = \"sfa-test-results-v1\";\n  var state = {};\n  try { state = JSON.parse(localStorage.getItem(KEY) || \"{}\") || {}; } catch (e) { state = {}; }\n  function save() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) {} }\n\n  var cases = Array.prototype.slice.call(document.querySelectorAll(\".case\"));\n  var labels = { ok: \"OK\", ng: \"NG\", hold: \"保留\" };\n\n  cases.forEach(function (c) {\n    var id = c.getAttribute(\"data-id\");\n    var res = c.querySelector(\".res\");\n    var memo = c.querySelector(\".memo input\");\n    if (memo) { memo.id = \"memo-\" + id; memo.setAttribute(\"aria-label\", id + \" のメモ\"); }\n    [\"ok\", \"ng\", \"hold\"].forEach(function (k) {\n      var b = document.createElement(\"button\");\n      b.type = \"button\"; b.className = k; b.textContent = labels[k];\n      b.id = \"res-\" + id + \"-\" + k;\n      b.setAttribute(\"aria-pressed\", \"false\");\n      b.addEventListener(\"click\", function () {\n        var cur = state[id] && state[id].r;\n        state[id] = state[id] || {};\n        state[id].r = cur === k ? \"\" : k;\n        save(); render();\n      });\n      res.appendChild(b);\n    });\n    if (memo) {\n      memo.value = (state[id] && state[id].m) || \"\";\n      memo.addEventListener(\"input\", function () { state[id] = state[id] || {}; state[id].m = memo.value; save(); });\n    }\n  });\n\n  function render() {\n    var n = { ok: 0, ng: 0, hold: 0 };\n    cases.forEach(function (c) {\n      var id = c.getAttribute(\"data-id\"); var r = (state[id] && state[id].r) || \"\";\n      c.classList.remove(\"is-ok\", \"is-ng\", \"is-hold\");\n      if (r) { c.classList.add(\"is-\" + r); n[r]++; }\n      Array.prototype.forEach.call(c.querySelectorAll(\".res button\"), function (b) { b.setAttribute(\"aria-pressed\", String(b.className === r)); });\n    });\n    var total = cases.length, done = n.ok + n.ng + n.hold;\n    document.getElementById(\"t-total\").textContent = total;\n    document.getElementById(\"t-done\").textContent = done;\n    document.getElementById(\"t-ok\").textContent = n.ok;\n    document.getElementById(\"t-ng\").textContent = n.ng;\n    document.getElementById(\"t-hold\").textContent = n.hold;\n    document.getElementById(\"b-ok\").style.width = (n.ok / total * 100) + \"%\";\n    document.getElementById(\"b-ng\").style.width = (n.ng / total * 100) + \"%\";\n    document.getElementById(\"b-hold\").style.width = (n.hold / total * 100) + \"%\";\n  }\n  render();\n\n  document.getElementById(\"copy\").addEventListener(\"click\", function () {\n    var lines = [\"SFA テスト結果 \" + new Date().toLocaleString(\"ja-JP\"), \"\"];\n    cases.forEach(function (c) {\n      var id = c.getAttribute(\"data-id\"); var s = state[id] || {};\n      var title = c.querySelector(\".title\").textContent.trim();\n      lines.push([id, s.r ? labels[s.r] : \"未実施\", title, s.m || \"\"].join(\"\\t\"));\n    });\n    var text = lines.join(\"\\n\");\n    var btn = this;\n    function done(ok) { btn.textContent = ok ? \"コピーしました\" : \"コピーできませんでした\"; setTimeout(function () { btn.textContent = \"結果をコピー\"; }, 1800); }\n    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(function () { done(true); }, function () { done(false); });\n    else done(false);\n  });\n  document.getElementById(\"reset\").addEventListener(\"click\", function () {\n    state = {}; save();\n    cases.forEach(function (c) { var m = c.querySelector(\".memo input\"); if (m) m.value = \"\"; });\n    render();\n  });\n})();\n</script>\n\n</body>\n</html>\n"}};
